INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5137', 'spa', 'El cuello o la garganta; parte frontal y lateral del cuello, usada literal y figuradamente para expresar carga o afecto.', 'Designa el cuello como parte anatómica del cuerpo, y aparece en el NT en dos contextos vívidos. Primero, en los dichos sobre la piedra de molino (Mt 18:6; Mr 9:42; Lc 17:2), una piedra pesada se cuelga ''alrededor del cuello'' antes de ahogar al ofensor — imagen sombría de juicio. Segundo, en la parábola del hijo pródigo (Lc 15:20), el padre ''se echó sobre su cuello'' en un abrazo de bienvenida — la misma parte del cuerpo convertida ahora en lugar de tierno reencuentro. En Hch 15:10, Pedro habla de poner un ''yugo sobre el cuello'' de los creyentes gentiles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5140', 'spa', 'τρεῖς — tres; el número cardinal, que a menudo porta peso simbólico en las Escrituras.', 'El número cardinal τρεῖς (''tres'', neutro τρία) aparece 70 veces en el Nuevo Testamento. Desde los tiempos más remotos, el tres tuvo un significado especial tanto en la cultura griega como en la semítica, y el Nuevo Testamento lo intensifica: tres días en el corazón de la tierra (Mt 12:40), tres medidas de harina (Mt 13:33), las tres negaciones y las tres afirmaciones de Pedro, los tres testigos de 1 Juan 5:8. La palabra se declina en los tres géneros (τρεῖς masculino/femenino, τρία neutro) y aparece en formas de genitivo y dativo, pero ninguna de estas flexiones genera un sentido distinto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5141', 'spa', 'Temblar, estremecerse de miedo; ser sobrecogido físicamente por temor reverencial, pavor o asombro.', 'Describe una respuesta física involuntaria de temblor o estremecimiento, provocada por miedo, reverencia o la percepción súbita de la presencia divina. En Marcos 5:33 la mujer sanada de flujo de sangre se acerca «temblando» ante Jesús, y Lucas 8:47 relata la misma escena. En Hechos 9:5 (en algunos manuscritos) Saulo tiembla en el camino a Damasco. Segunda de Pedro 2:10 habla de seres celestiales ante quienes otros se estremecen. No se trata de mera ansiedad mental, sino de un temblor corporal visceral e involuntario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5142', 'spa', 'Alimentar, nutrir, amamantar, engordar o criar; abarca el sustento físico, la lactancia, el exceso y la crianza prolongada.', 'Verbo fundamental de sustento que se extiende desde Dios alimentando a los cuervos (Lc 12:24) hasta los ricos engordándose para el juicio (Stg 5:5). En su núcleo, τρέφω significa proveer alimento, pero el Nuevo Testamento lo despliega en un abanico notable: provisión divina para aves y personas, una región que abastece de víveres a una casa real (Hch 12:20), la lactancia materna (Lc 23:29) y la crianza prolongada de un niño en su pueblo natal (Lc 4:16). El verbo conlleva un matiz de dependencia: quienes son alimentados por τρέφω dependen de un proveedor mayor que ellos mismos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5143', 'spa', 'Correr; literalmente del movimiento veloz a pie, figuradamente del esfuerzo en la carrera de la fe o de un mensaje que se difunde. Τρέχω es uno de los', 'Correr; literalmente del movimiento veloz a pie, figuradamente del esfuerzo en la carrera de la fe o de un mensaje que se difunde. Τρέχω es uno de los verbos más cinéticos del Nuevo Testamento. En los Evangelios capta la urgencia física pura: las mujeres corren desde la tumba vacía (Mt 28:8), el padre corre a abrazar a su hijo pródigo (Lc 15:20), Pedro y el discípulo amado corren hacia el sepulcro (Jn 20:2-4). Pablo luego se apropia de la imagen atlética para la vida espiritual, evocando el estadio griego: «He corrido la carrera» (Gál 2:2; Fil 2:16). Hebreos 12:1 exhorta a los creyentes a «correr con perseverancia». En una extensión notable, Pablo ora para que «la palabra del Señor corra» — se difunda con rapidez y sin impedimento (2 Tes 3:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5144', 'spa', 'Treinta — número cardinal que aparece en rendimientos agrícolas, cantidades monetarias y referencias de edad o duración. El numeral indeclinable τριάκ', 'Treinta — número cardinal que aparece en rendimientos agrícolas, cantidades monetarias y referencias de edad o duración. El numeral indeclinable τριάκοντα (triakonta) significa ''treinta'' y aparece en contextos teológicamente significativos. En la parábola del sembrador, algunas semillas rinden treinta por uno (Mateo 13:8, 23; Marcos 4:8, 20). Judas traiciona a Jesús por treinta piezas de plata (Mateo 26:15), que devuelve lleno de remordimiento (Mateo 27:3), y los sacerdotes las usan para comprar el campo del alfarero (Mateo 27:9), haciéndose eco de Zacarías 11:12-13. Jesús tenía ''como treinta años'' cuando comenzó su ministerio (Lucas 3:23). El enfermo de Betesda llevaba treinta y ocho años enfermo (Juan 5:5). Pablo cuenta cuatrocientos treinta años desde la promesa hasta la ley (Gálatas 3:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5147', 'spa', 'senda, vereda, camino trillado; ruta desgastada por el uso repetido de los viajeros', 'Una τρίβος es una senda formada por el paso repetido de muchos pies, un camino rústico y humilde, distinto de una calzada formal (ὁδός). Puede usarse metafóricamente para describir el curso de vida o conducta de una persona. En el Nuevo Testamento aparece únicamente en la cita sinóptica de Isaías 40:3, donde preparar el camino del Señor implica enderezar sus «sendas». La imagen evoca tanto la antigua costumbre de preparar caminos para visitas reales como la preparación espiritual necesaria para recibir al Mesías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5151', 'spa', 'τρίς -- tres veces; adverbio numeral que indica repetición triple.', 'τρίς -- tres veces; adverbio numeral que indica repetición triple.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5154', 'spa', 'Tercero; el numeral ordinal ''tercero'', también usado como fracción ''un tercio'' y adverbialmente como ''por tercera vez''.', 'Τρίτος es la forma ordinal de τρεῖς (''tres'') y aparece en el Nuevo Testamento con tres funciones gramaticales distintas. Como ordinal simple, marca el ''tercer día'' de las predicciones de la resurrección de Cristo (Mt 16:21) y secuencias en parábolas. En Apocalipsis se convierte en término técnico fraccionario: ''la tercera parte de la tierra'', ''la tercera parte del mar'', midiendo el alcance terrible pero aún parcial del juicio divino. Y en uso adverbial, narra las repeticiones dramáticas de la Escritura: la tercera negación de Pedro, Jesús orando ''por tercera vez'' en Getsemaní (Mt 26:44) y el Señor resucitado apareciendo a sus discípulos ''la tercera vez'' junto al mar de Tiberíades (Jn 21:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5156', 'spa', 'Temblor, estremecimiento; sacudida física provocada por temor, reverencia o sumisión ante Dios o la autoridad.', 'Este sustantivo designa un temblor visible y corporal que surge del miedo profundo, el asombro reverente o la sumisión. Ante el sepulcro vacío, las mujeres huyeron presas de ''temblor y espanto'' (Marcos 16:8). Pablo llegó a Corinto ''con debilidad, temor y mucho temblor'' (1 Corintios 2:3), modelando la dependencia de Dios más que la destreza retórica. La expresión ''temor y temblor'' se vuelve casi formulaica en las cartas paulinas: describe la solicitud con que los corintios recibieron a Tito (2 Corintios 7:15), la actitud apropiada de los siervos ante sus amos (Efesios 6:5) y la postura del creyente que trabaja en su salvación (Filipenses 2:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5158', 'spa', 'Manera, modo, forma -- el modo o método por el cual algo se realiza.', 'Manera, modo, forma -- el modo o método por el cual algo se realiza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5160', 'spa', 'Alimento, nutrición o sustento; lo que se come para mantener la vida, usado literalmente de las comidas y figuradamente de la provisión espiritual. Τρ', 'Alimento, nutrición o sustento; lo que se come para mantener la vida, usado literalmente de las comidas y figuradamente de la provisión espiritual. Τροφή abarca todo lo que se consume para el sustento corporal, desde la dieta austera de Juan el Bautista de langostas y miel silvestre (Mt 3:4) hasta las raciones regulares que un mayordomo fiel distribuye (Mt 24:45; Lc 12:42). Jesús enseña que la vida es más que el alimento (Mt 6:25; Lc 12:23), relativizando su importancia sin negar su necesidad. En Hechos, la palabra describe tanto comidas ordinarias (Hch 2:46; 27:33-36) como el concepto general de provisiones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5161', 'spa', 'Trófimo, cristiano gentil de Éfeso que acompañó a Pablo en sus viajes misioneros', 'Trófimo era un creyente de Asia (probablemente efesio) que viajó con Pablo durante su ministerio posterior. Su nombre, que en griego significa «nutritivo» o «hijo adoptivo», era común en el mundo grecorromano. Su presencia con Pablo en Jerusalén provocó un motín cuando los judíos acusaron falsamente a Pablo de haber introducido a este gentil en los atrios interiores del templo, profanando el espacio sagrado (Hechos 21:27-29). La acusación, aunque falsa, reveló las tensiones explosivas en torno a la inclusión de los gentiles en la comunidad mesiánica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5166', 'spa', 'cosechar, vendimiar, recoger; recolectar frutos o cosechas, especialmente uvas o grano', 'Este verbo describe la acción de cosechar frutos y cultivos, más comúnmente la vendimia. El sustantivo raíz τρυγή significa «cosecha» o «cultivo». Aunque puede referirse a recoger cualquier fruto, la asociación vitícola es predominante, de ahí su uso en la enseñanza de Jesús sobre las uvas y los espinos (Lucas 6) y en la imaginería apocalíptica de la cosecha en Apocalipsis. La cosecha antigua era un trabajo intensamente estacional que requería muchas manos; el término evoca tanto la abundancia como la urgencia de recoger lo que está maduro antes de que se malogre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5174', 'spa', 'Troas -- ciudad portuaria de Alejandría Tróade en el noroeste de Asia Menor, escala clave en los viajes de Pablo.', 'Troas (nombre completo Alejandría Tróade) era una importante ciudad portuaria romana en la costa egea de la región de Tróade, en el noroeste de Asia Menor (actual Turquía). Servía como puerta de entrada principal entre Asia y Macedonia, y ocupa un lugar prominente en los viajes misioneros de Pablo. En Troas, Pablo recibió la visión del macedonio que lo llamaba a Europa (Hechos 16:8-10). Más tarde regresó para una estancia de una semana durante la cual Eutico cayó de una ventana (Hechos 20:5-12). Pablo también menciona haber dejado una capa y unos pergaminos en Troas (2 Timoteo 4:13). El nombre se mantiene invariable en todos los idiomas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5175', 'spa', 'Trogilión; promontorio y ciudad en Jonia frente a la isla de Samos', 'Trogilión era un promontorio y pequeña ciudad en la costa de Jonia, situada frente a la isla de Samos. Se menciona en algunos manuscritos de Hechos como punto de escala durante el tercer viaje misionero de Pablo. El nombre aparecía con diversas grafías en las fuentes antiguas, reflejando la fluidez en la transcripción de topónimos. Aunque algunos manuscritos importantes del Nuevo Testamento omiten esta referencia, otros la conservan como detalle geográfico del viaje costero de Pablo. El lugar era bien conocido por los navegantes de la antigüedad como punto de referencia donde los barcos podían fondear en el estrecho entre el continente y Samos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5176', 'spa', 'Trōgō -- comer, masticar, mascar; verbo vívido que enfatiza el acto físico y corporal de comer.', 'A diferencia del genérico esthiō (''comer''), trōgō posee una cualidad vívida, casi onomatopéyica: originalmente describía el roer y mascar de los animales, extendiéndose luego al consumo humano de vegetales y frutas crudas. Su uso neotestamentario se concentra en Juan 6, donde Jesús declara ''el que mastica mi carne y bebe mi sangre tiene vida eterna'' (Juan 6:54). La elección deliberada de este verbo visceral en lugar de esthiō, empleado antes en el mismo discurso, intensifica la escandalosa fisicalidad de la enseñanza del Pan de Vida. Mateo 24:38 lo usa para describir a quienes ''comían y bebían'' antes del diluvio, subrayando su absorción mundana y corporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5177', 'spa', 'Obtener o alcanzar algo buscado; suceder o acontecer por casualidad; (como participio) ordinario, común.', 'Obtener o alcanzar algo buscado; suceder o acontecer por casualidad; (como participio) ordinario, común.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5179', 'spa', 'Marca, huella, patrón, modelo o ejemplo; desde la impresión de un golpe hasta un paradigma moral, prefiguración o imagen de ídolo. Derivado del verbo ', 'Marca, huella, patrón, modelo o ejemplo; desde la impresión de un golpe hasta un paradigma moral, prefiguración o imagen de ídolo. Derivado del verbo «golpear», este sustantivo avanza desde la marca física dejada por un golpe hasta significados cada vez más abstractos. En Jn 20:25 Tomás exige ver la «marca» de los clavos — la huella literal en la carne. Pero Pablo lo transforma en un poderoso término ético: los creyentes deben seguir los «ejemplos» apostólicos (Fil 3:17), y Adán es un «tipo» que prefigura a Cristo (Rom 5:14). La palabra también designa el plano divino mostrado a Moisés para el tabernáculo (Hch 7:44).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5180', 'spa', 'Golpear o azotar; dar a alguien con la mano, el puño o un instrumento, ya sea activamente o como víctima pasiva.', 'Golpear o azotar; dar a alguien con la mano, el puño o un instrumento, ya sea activamente o como víctima pasiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5182', 'spa', 'turbar, agitar, perturbar; revolver un líquido, empujar entre multitudes o experimentar inquietud interior', 'Este verbo significa principalmente agitar o perturbar. Originalmente se usaba para remover barro o arcilla en el agua, produciendo corrientes turbias. De la agitación física pasó a describir los empujones entre multitudes y luego la perturbación emocional interior. El Nuevo Testamento emplea una variante en la queja de Marta, quien se siente turbada o distraída por muchas cosas. Autores posteriores lo usaron para referirse a celebraciones bulliciosas, quizá por la idea de ''revolver el ambiente'' en las fiestas. La palabra captura la transición de lo físico a lo psicológico, un camino metafórico habitual en griego donde la agitación material servía de modelo para los estados mentales y emocionales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5184', 'spa', 'Tiro — antigua ciudad costera fenicia, citada en oráculos proféticos de juicio y en el ministerio galileo de Jesús. El nombre propio Τύρος (Tyros) des', 'Tiro — antigua ciudad costera fenicia, citada en oráculos proféticos de juicio y en el ministerio galileo de Jesús. El nombre propio Τύρος (Tyros) designa a Tiro, la rica ciudad portuaria fenicia en la costa mediterránea del actual Líbano. Jesús invoca a Tiro en sus ayes contra Corazín y Betsaida: ''Si en Tiro y en Sidón se hubieran hecho los milagros que se han hecho en vosotras, tiempo ha que se hubieran arrepentido'' (Mateo 11:21-22; Lucas 10:13-14). Se retira a la región de Tiro y Sidón, donde sana a la hija de la mujer sirofenicia (Mateo 15:21; Marcos 7:24, 31). Multitudes de Tiro vienen a oírle (Marcos 3:8; Lucas 6:17). En Hechos, el barco de Pablo atraca en Tiro, donde permanece con discípulos siete días (Hechos 21:3, 7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5185', 'spa', 'Ciego, sin vista; literalmente de incapacidad física para ver, figuradamente de ignorancia espiritual o falta de percepción moral.', 'Adjetivo común que describe a quienes no pueden ver, usado a lo largo de los Evangelios especialmente para las personas que Jesús sana: los dos ciegos de Mateo 9, el ciego de nacimiento en Juan 9, el ciego Bartimeo. Casi todas las apariciones son físicas, y la evidencia multilingüe lo confirma: el español ''ciego'', el francés ''aveugle'' y el alemán ''blind'' convergen en un único significado concreto. Sin embargo, en Apocalipsis 3:17 la palabra toma un giro metafórico llamativo, dirigida a la iglesia autosatisfecha de Laodicea, que no puede percibir su propia pobreza espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5186', 'spa', 'cegar, dejar ciego; causar pérdida de visión o percepción, ya sea literal o metafóricamente', 'Este verbo significa privar de la vista, ya sea física o mentalmente. El griego clásico lo usaba tanto en sentido literal como metafórico, para referirse a la ceguera intelectual o moral. En el Nuevo Testamento aparece exclusivamente en sentido metafórico: una ceguera espiritual y mental que impide ver la verdad. El agente que ciega varía: Dios, Satanás o el pecado mismo pueden cegar las mentes y los corazones. Esta imagen se nutre del lenguaje de la Biblia hebrea sobre el endurecimiento de corazones y el cierre de ojos como juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5187', 'spa', 'envanecerse, hincharse de orgullo; estar cegado por la arrogancia o la presunción', 'Este verbo en perfecto pasivo describe un estado de envanecimiento o delirio causado por la soberbia, una vanidad inflada por el orgullo, el éxito o la autoimportancia. El sustantivo raíz τῦφος significa «humo» o «vanidad», y el verbo sugiere estar nublado o aturdido por los vapores del orgullo. Es más fuerte que el simple orgullo: implica una especie de intoxicación mental o delirio. El Nuevo Testamento lo usa exclusivamente en las Epístolas Pastorales como un vicio que deben evitar los líderes eclesiásticos y como rasgo característico de los falsos maestros y los apóstatas de los últimos tiempos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5190', 'spa', 'Tíquico: cristiano de Asia Menor, compañero de confianza de Pablo y portador de sus cartas.', 'Tíquico (Τυχικός) fue un creyente de la provincia romana de Asia que se convirtió en uno de los colaboradores más fieles de Pablo, sirviendo como emisario personal y portador de epístolas. Acompañó al apóstol en su último viaje a Jerusalén (Hechos 20:4) y más tarde llevó las cartas a los Efesios y a los Colosenses, con el encargo de informar sobre las circunstancias de Pablo y alentar a las iglesias (Efesios 6:21-22; Colosenses 4:7-8). Pablo lo llama ''hermano amado y fiel ministro en el Señor'', un elogio que refleja la alta estima en que lo tenía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5193', 'spa', 'Vidrioso, hecho de vidrio o cristal; que tiene la apariencia o sustancia del vidrio', 'Este adjetivo describe algo hecho de vidrio o que posee cualidades cristalinas: transparente, liso, resplandeciente. En la antigüedad, el vidrio era un material de lujo, y la imagen de un mar de vidrio evoca belleza y perfección supremas. El término aparece exclusivamente en las visiones del salón del trono en Apocalipsis, donde el templo celestial contiene un mar vidrioso sin paralelo en el tabernáculo terrenal. La imagen podría evocar la fuente de bronce del templo de Salomón, pero transformada en algo trascendente e inmóvil, sugiriendo paz y estabilidad perfectas ante el trono de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5195', 'spa', 'ὑβρίζω: tratar con violenta insolencia; maltratar, ultrajar o abusar de alguien de manera vergonzosa.', 'El verbo ὑβρίζω conlleva la fuerza de un abuso deliberado y despectivo: no una simple ofensa verbal, sino un maltrato ultrajante que viola la dignidad y el honor de una persona. En el griego clásico denotaba el exceso arrogante (ὕβρις) expresado mediante violencia o injuria. El Nuevo Testamento conserva esta gravedad: los siervos del rey maltratan vergonzosamente a los invitados a la boda (Mateo 22:6), Jesús profetiza que será insultado y escupido (Lucas 18:32), y Pablo y Silas son golpeados y ultrajados en Filipos (1 Tesalonicenses 2:2). El español ''ultrajar'' capta bien el elemento de ultraje que distingue a este verbo de términos más suaves para la ofensa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5196', 'spa', 'Ultraje, afrenta, maltrato; violencia desmedida o abuso nacido de la arrogancia o el desprecio', 'Este sustantivo designa un trato violento y abusivo motivado por la arrogancia o el desprecio, no una violencia por interés sino por la imposición de dominio. El griego clásico lo empleaba para la insolencia que nace del orgullo y la fuerza, ese tipo de abuso que deshonra a la víctima. Puede abarcar desde insultos verbales hasta agresiones físicas, unidos por el elemento de agresión despectiva. En el Nuevo Testamento describe tanto las dificultades del ministerio apostólico como los peligros de la navegación, mostrando cómo la soberbia se manifiesta en múltiples formas de maltrato.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5198', 'spa', 'Estar sano o saludable; referido a la doctrina, ser íntegro y libre de error; referido a personas, estar físicamente bien.', 'Estar sano o saludable; referido a la doctrina, ser íntegro y libre de error; referido a personas, estar físicamente bien.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5199', 'spa', 'Sano, en buen estado físico; figuradamente íntegro o sano (referido a la doctrina, enseñanza o palabras).', 'Sano, en buen estado físico; figuradamente íntegro o sano (referido a la doctrina, enseñanza o palabras).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5201', 'spa', 'Tinaja, cántaro; vasija grande para contener o transportar agua', 'La ὑδρία era una vasija grande de cerámica con tres asas —dos laterales para levantarla y una vertical para verter— diseñada específicamente para transportar agua. Las mujeres solían llevarlas a los pozos o manantiales, equilibrándolas sobre la cabeza o los hombros. Su capacidad variaba, pero podían contener entre 20 y 30 litros. Aunque su significado raíz es «cántaro de agua», el término podía aplicarse a otras vasijas grandes. Todos los usos neotestamentarios son literales, describiendo tinajas reales en el ministerio de Jesús, convirtiendo este objeto cotidiano en partícipe de momentos milagrosos y evangelísticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5204', 'spa', 'Agua; la sustancia natural esencial, usada literal y simbólicamente para vida, purificación y bautismo.', 'El griego ὕδωρ abarca toda la gama de referencias al agua en el Nuevo Testamento: ríos, mares, pozos, lluvia, agua para beber y el agua de la purificación ritual y el bautismo. El Evangelio de Juan hace un uso teológico especialmente rico del término: el milagro del agua convertida en vino en Caná, el agua viva ofrecida a la samaritana (Jn 4:10) y el agua y la sangre que brotan del costado de Cristo (Jn 19:34). El agua bautismal lleva peso pactual, pues Juan el Bautista distingue su bautismo en agua del bautismo venidero en el Espíritu (Mt 3:11). Las resonancias teológicas son inmensas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5205', 'spa', 'ὑετός — lluvia, especialmente aguacero abundante; precipitación enviada o retenida por voluntad divina', 'El sustantivo ὑετός designa la lluvia, en particular el aguacero copioso, diferenciándose en el griego clásico de la llovizna continua (ψεκάς) o la lluvia sostenida (ὄμβρος). En el Nuevo Testamento cada aparición lleva carga teológica: Dios da lluvia del cielo como testimonio de su bondad (Hch 14:17), la lluvia cae sobre la tierra y trae bendición a los fieles (Heb 6:7), la oración de Elías cierra y abre de nuevo los cielos (Stg 5:18), y los dos testigos poseen poder para cerrar el cielo e impedir que llueva (Ap 11:6). No presenta polisemia: todas las ocurrencias apuntan al fenómeno de la lluvia bajo la soberanía de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5206', 'spa', 'υἱοθεσία — adopción como hijo; acto jurídico y espiritual de ser incorporado como hijo en una familia', 'Υἱοθεσία (de υἱός ''hijo'' + θέσις ''colocación'') es el término distintivamente paulino para la adopción: el acto legal por el cual alguien que no nació en una familia recibe plena condición de hijo y heredero. Pablo lo emplea en un registro profundamente teológico: los creyentes reciben el «espíritu de adopción» por el cual claman «Abba, Padre» (Ro 8:15), aguardan la consumación plena de su adopción en la resurrección del cuerpo (Ro 8:23), y la adopción figura entre los privilegios del pacto de Israel (Ro 9:4). El propósito mismo de la obra redentora de Cristo fue «que recibiésemos la adopción de hijos» (Gá 4:5). El alemán Sohnschaft (''filiación'') capta el matiz relacional, mientras que el español adopción conserva la metáfora jurídica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5207', 'spa', 'Hijo, descendiente o persona caracterizada por una cualidad; sentido literal y en modismo semítico (''hijo de...'').', 'Υἱός es uno de los sustantivos con mayor carga teológica del Nuevo Testamento griego. Sus 382 ocurrencias abarcan desde el sentido literal de ''descendiente varón'' (Mt 1:21) hasta el título mesiánico ''Hijo del Hombre'' y la confesión cristológica suprema ''Hijo de Dios'' (Mt 3:17; 16:16). Siguiendo el modismo semítico, también denota pertenencia a una categoría: ''hijos de la luz'' (Jn 12:36), ''hijos de Abraham'' (Gá 3:7), ''hijos del reino'' (Mt 8:12). Esta amplitud obliga a las traducciones a transitar entre los registros biológico, relacional y metafórico dentro de un solo lexema — hijo, fils, Sohn soportan todos ese mismo peso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5209', 'spa', 'a vosotros/ustedes (acusativo plural); forma acusativa del pronombre personal de segunda persona plural', 'Esta es la forma ὑμᾶς, el acusativo plural del pronombre de segunda persona, equivalente a ''os'' o ''a ustedes'' como objeto directo al dirigirse a varias personas. El griego distinguía cuidadosamente las formas singulares de las plurales, a diferencia del inglés moderno. Esta forma aparecía constantemente en las epístolas neotestamentarias donde los apóstoles se dirigían a comunidades enteras: ''os exhorto'', ''Dios os ama'', ''os envío''. Las formas plurales eran esenciales en el discurso epistolar, donde los autores se dirigían a las iglesias como cuerpos colectivos. El caso acusativo marcaba a los receptores de la acción, haciendo de esta forma algo fundamental para mandamientos, bendiciones, advertencias y expresiones de solicitud apostólica hacia las congregaciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5210', 'spa', 'vosotros/ustedes (nominativo plural); pronombre de segunda persona plural como sujeto', 'Esta es la forma ὑμεῖς, el nominativo plural del pronombre de segunda persona, que significa ''vosotros'' o ''ustedes'' como sujeto al dirigirse a un grupo. El rico sistema pronominal del griego distinguía entre singular y plural, y el caso nominativo señalaba quién realizaba la acción. Los escritores neotestamentarios lo usaban enfáticamente para contrastar a sus destinatarios con otros: ''vosotros sois la luz del mundo'', ''pero vosotros no estáis en la carne''. La forma podía aparecer sola con valor enfático (''vosotros mismos sabéis'') o acompañar al verbo donde en español bastaría la conjugación. Marcaba la identidad colectiva y la responsabilidad compartida en la instrucción apostólica dirigida a comunidades de creyentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5212', 'spa', 'Vuestro, de vosotros — pronombre posesivo enfático de segunda persona del plural que atribuye posesión o asociación a los interlocutores. El adjetivo ', 'Vuestro, de vosotros — pronombre posesivo enfático de segunda persona del plural que atribuye posesión o asociación a los interlocutores. El adjetivo posesivo ὑμέτερος (hymeteros) es la forma enfática del posesivo de segunda persona del plural, que significa ''vuestro'' o ''de vosotros''. Suele aparecer cuando el hablante establece un contraste marcado. Jesús declara: ''Vuestro es el reino de Dios'' (Lucas 6:20), distingue ''vuestro tiempo'' del suyo propio (Juan 7:6), apela a ''vuestra ley'' en el debate con los fariseos (Juan 8:17), y advierte que perseguirlo a él implica ser perseguidos ellos también (Juan 15:20). En Lucas 16:12, la fidelidad con lo ajeno merece recibir ''lo que es vuestro''. Pablo lo emplea para expresar pertenencia mutua y asuntos espirituales (1 Cor 15:31; 16:17; Gál 6:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5213', 'spa', 'vosotros (dativo plural); forma dativa que significa ''a vosotros'' o ''para vosotros'' al dirigirse a varias personas', 'Esta es ὑμῖν, la forma dativa plural del pronombre de segunda persona, que significa ''a vosotros'' o ''para vosotros'' al dirigirse a grupos. El caso dativo marcaba objetos indirectos, destinatarios de beneficios o personas afectadas por una acción. Las epístolas del Nuevo Testamento empleaban constantemente esta forma en promesas (''gracia a vosotros y paz''), instrucciones (''os digo'') y explicaciones (''este misterio os es revelado''). El dativo plural era esencial en el género epistolar, donde los apóstoles se dirigían a iglesias enteras, estructurando las relaciones de dar y recibir entre Dios, los maestros apostólicos y las comunidades creyentes, indicando quién recibía gracia, enseñanza, mandamientos y aliento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5214', 'spa', 'Cantar un himno, entonar alabanzas a Dios; adoración litúrgica mediante canto vocal.', 'Designa el acto de cantar alabanza sagrada, ya sea en el culto formal o en la devoción espontánea. En la Última Cena (Mt 26:30; Mc 14:26), Jesús y los discípulos cantaron un himno antes de salir al Monte de los Olivos, casi con certeza los salmos del Hallel (Sal 113-118). En Hechos 16:25, Pablo y Silas cantaban himnos a Dios a medianoche en la cárcel de Filipos, y Hebreos 2:12 cita el Salmo 22:22 donde el Mesías declara «te alabaré». El verbo griego fusiona la idea de alabanza y canto en una sola acción de adoración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5216', 'spa', 'vuestro, de vosotros (genitivo plural); forma posesiva del pronombre de segunda persona plural', 'Esta es ὑμῶν, la forma genitiva plural del pronombre de segunda persona, que significa ''de vosotros'' o ''vuestro'' al dirigirse a grupos. El griego utilizaba el caso genitivo para la posesión en lugar de adjetivos posesivos separados. Esta forma aparecía constantemente en la literatura epistolar: ''vuestra fe'', ''vuestro amor'', ''vuestra obra''. Permitía a los apóstoles hablar sobre las características colectivas, posesiones o responsabilidades de las comunidades. También podía indicar origen (''de vosotros'') o relación (''vuestros hermanos''). En la instrucción ética del Nuevo Testamento, ''vuestro'' señalaba tanto lo que los creyentes poseían en Cristo como lo que debían demostrar en su conducta y carácter.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5217', 'spa', 'Ir, dirigirse, partir — verbo de movimiento frecuente en mandatos, que a veces implica retiro o partida.', 'Verbo de movimiento común en los Evangelios, que aparece frecuentemente en mandatos directos de Jesús: ''Ve, muéstrate al sacerdote'' (Mt 8:4), ''Ve, vende lo que tienes'' (Mt 19:21). Aunque la gran mayoría de sus 80 apariciones simplemente significan ''ir'' o ''dirigirse'', un subconjunto pequeño pero teológicamente significativo porta el sentido más grave de ''irse, retirarse'', como cuando Jesús pregunta a los Doce: ''¿También vosotros queréis iros?'' (Jn 6:67). El español distingue estos matices con ''id/voy'' frente a ''iros'', confirmando la diferencia semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5218', 'spa', 'Obediencia -- el acto o disposición de someterse a la autoridad, especialmente a Dios o al evangelio.', 'Obediencia -- el acto o disposición de someterse a la autoridad, especialmente a Dios o al evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5219', 'spa', 'Obedecer, someterse a la autoridad; abrir una puerta o responder a un llamado.', 'Obedecer, someterse a la autoridad; abrir una puerta o responder a un llamado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5221', 'spa', 'Salir al encuentro de alguien o encontrarse con una persona, ya sea en saludo, súplica o confrontación militar. Formado a partir de ὑπό (''hacia'') y ἀν', 'Salir al encuentro de alguien o encontrarse con una persona, ya sea en saludo, súplica o confrontación militar. Formado a partir de ὑπό (''hacia'') y ἀντάω (''encontrarse cara a cara''), este verbo describe un movimiento deliberado hacia una persona que se aproxima. La mayoría de las apariciones en el Nuevo Testamento describen encuentros neutrales o positivos: los endemoniados gadarenos salen al encuentro de Jesús (Mt 8:28), el siervo corre a informar sobre la curación del muchacho (Jn 4:51), y las mujeres se encuentran con el Señor resucitado (Mt 28:9). Sin embargo, en Lucas 14:31 un rey sale a ''enfrentarse'' con un ejército que avanza, y la evidencia multilingüe revela el matiz hostil: en hindi ''saamna karne ko'' (confrontar) y en coreano ''맞서기를'' (oponerse), distinguiendo este sentido militar de los demás encuentros de bienvenida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5222', 'spa', 'Encuentro, recibimiento; acción de salir al encuentro de alguien, especialmente en recepción formal', 'Este sustantivo describe la acción de salir al encuentro de alguien que se acerca, frecuentemente con el sentido de una recepción formal o comitiva de bienvenida. En la cultura helenística, era costumbre que los ciudadanos salieran de la ciudad para recibir y honrar a dignatarios visitantes. El término aparece en contextos de anticipación y encuentro: personas que salen al encuentro de Jesús, ya sea con hostilidad (Mateo 8) o con honra (Mateo 25, Juan 12). Implica mayor intencionalidad que un encuentro casual; es un movimiento deliberado hacia una llegada esperada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5224', 'spa', 'comenzar, tomar la iniciativa; existir previamente, pertenecer a', 'Este verbo combina dos significados distintos. El primero capta la idea de iniciar o dar el primer paso en una acción, a menudo con matices morales: quién asestó el primer golpe o comenzó la injusticia. El segundo sentido, más frecuente en el Nuevo Testamento, expresa existir de antemano o pertenecer a alguien, describiendo posesiones o cualidades inherentes. Ambos usos comparten la noción de prioridad o precedencia, ya sea en el tiempo o en la posesión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5225', 'spa', 'Existir o hallarse en un estado; sustantivado como posesiones o bienes pertenecientes a alguien.', 'Verbo versátil que en el Nuevo Testamento funciona casi siempre como sinónimo cercano de εἰμί, expresando existencia o un estado de ser. Lucas lo emplea con frecuencia para describir la identidad o condición de alguien (Lc 8:41, ''era un principal de la sinagoga''). Cuando el participio neutro plural τὰ ὑπάρχοντα se sustantiva, se convierte en término estándar para las posesiones o bienes de una persona, un uso que Jesús aprovecha incisivamente en parábolas sobre la riqueza y la mayordomía (Mt 25:14; Lc 12:33). El español ''bienes'' y el alemán Besitz captan bien el paso del ser abstracto a las pertenencias concretas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5228', 'spa', 'Preposición/adverbio: en favor de, por; por encima de, más que; acerca de; sobremanera.', 'Una de las preposiciones con mayor peso teológico del Nuevo Testamento, ὑπέρ expresa primordialmente la acción en favor de otro o en su beneficio — central en el lenguaje paulino de la expiación (''Cristo murió ὑπέρ nosotros''). Con genitivo indica representación o sustitución; con acusativo significa por encima de o más allá, adquiriendo fuerza comparativa. En composición intensifica verbos para expresar sobreabundancia, como en Efesios 3:20 donde Dios hace ὑπερεκπερισσοῦ — infinitamente más de lo que pedimos. El español ''por'' capta el núcleo benefactivo, mientras que ''sobre'' y ''más allá de'' cubren el abanico espacial-comparativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5229', 'spa', 'Enaltecerse, exaltarse por encima de otros; en voz media, ser elevado en orgullo o soberbia', 'Este verbo describe el acto de elevarse o ser exaltado por encima de los demás, típicamente en sentido negativo de orgullo o arrogancia. Pablo lo usa dos veces en el mismo versículo (2 Corintios 12:7) para describir el peligro de «enaltecerse sobremanera» a causa de las revelaciones, una tentación contrarrestada por su aguijón en la carne. La figura del Anticristo en 2 Tesalonicenses 2:4 «se exalta» sobre todo lo que se llama Dios. El sentido reflexivo subraya que esta elevación orgullosa es autoinfligida, un exceder los límites propios por soberbia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5231', 'spa', 'Muy por encima, por encima de todo; forma intensificada que indica posición o estatus supremo', 'Este adverbio/preposición compuesto (ὑπέρ, «sobre» + ἄνω, «arriba») intensifica el sentido de «arriba» para expresar «muy por encima» o «alto sobre todo». No indica solamente altura física, sino supremacía, superioridad y trascendencia. En el Nuevo Testamento se emplea exclusivamente para describir la exaltación suprema de Cristo: su posición muy por encima de todo poder, autoridad y cielo. El término subraya la soberanía absoluta de Cristo dentro de la jerarquía cósmica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5235', 'spa', 'ὑπερβάλλω — sobrepasar, exceder o ir más allá de toda medida; ser extraordinario en grado', 'El verbo ὑπερβάλλω (literalmente ''lanzar más allá'') es empleado exclusivamente por Pablo, siempre en forma participial, para describir realidades que exceden todo punto de comparación. Es un término reservado para lo superlativo: la gloria incomparable del nuevo pacto eclipsa la del antiguo (2 Co 3:10), la gracia sobreabundante de Dios se desborda hacia los corintios (2 Co 9:14), y la extraordinaria grandeza del poder de Dios actúa en los creyentes (Ef 1:19). De esta misma raíz procede la palabra castellana «hipérbole».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5236', 'spa', 'Grado superlativo, exceso, medida extraordinaria; usado por Pablo para expresar lo que sobrepasa toda escala normal.', 'Sustantivo que designa aquello que excede los límites normales: un grado extraordinario o un exceso fuera de toda proporción. Pablo lo emplea casi exclusivamente, a menudo en la expresión fija καθ'' ὑπερβολήν (sobremanera, en extremo). Habla de que el pecado llega a ser «sobremanera pecaminoso» (Ro 7:13), de una aflicción en Asia «excesiva, más allá de nuestras fuerzas» (2 Co 1:8), y de un «eterno peso de gloria que sobrepasa toda comparación» (2 Co 4:17). El español tomó prestada la palabra directamente como «hipérbole», pero en manos de Pablo no es exageración retórica, sino descripción de realidades que genuinamente superan las categorías humanas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5242', 'spa', 'ὑπερέχω — estar por encima, superar o sobresalir; ocupar una posición superior en rango o valor', 'El verbo ὑπερέχω (literalmente ''sostener por encima'') denota superioridad tanto en rango como en cualidad. Pablo lo emplea en registros sociales y espirituales: las autoridades gobernantes son poderes «superiores» que deben respetarse (Ro 13:1), cada creyente ha de estimar a los demás como superiores a sí mismo (Fil 2:3), conocer a Cristo tiene un valor que sobrepasa todo lo demás (Fil 3:8), y la paz de Dios sobrepasa todo entendimiento (Fil 4:7). Pedro igualmente exhorta a la sumisión al emperador como autoridad «suprema» (1 P 2:13). El término abarca así tanto la jerarquía institucional como la trascendencia espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5244', 'spa', 'ὑπερήφανος — arrogante, soberbio, altivo; quien se exalta a sí mismo por encima de los demás con desdén', 'El adjetivo ὑπερήφανος (literalmente ''el que se muestra por encima'') describe a una persona hinchada de orgullo desmedido que mira a los demás con desprecio. Va más allá de la simple confianza en sí mismo y entra en el terreno de la insolencia: un orgullo que se levanta contra el prójimo y contra Dios. En el Magnificat, María proclama que Dios «esparció a los soberbios (ὑπερηφάνους) en el pensamiento de sus corazones» (Lc 1:51), y tanto Santiago como Pedro citan Proverbios 3:34: «Dios resiste a los soberbios, y da gracia a los humildes» (Stg 4:6; 1 P 5:5). En los catálogos de vicios de Ro 1:30 y 2 Ti 3:2, aparece junto a blasfemos y jactanciosos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5253', 'spa', 'Aposento alto, sala superior; habitación en el piso alto de una casa usada para oración, reuniones o alojamiento.', 'Designa una habitación elevada en una vivienda de varios pisos, por lo general el espacio más privado y honorable de un hogar del Cercano Oriente antiguo. En Hechos 1:13 los discípulos se reúnen en «el aposento alto» tras la ascensión, un lugar que se volvió emblemático en la memoria cristiana. Hechos 9:37 y 9:39 sitúan el cuerpo de Tabita en un aposento alto en Jope, y Hechos 20:8 describe la sala superior bien iluminada en Troas donde Pablo predicó hasta la medianoche. El término refleja la realidad arquitectónica de las casas mediterráneas del primer siglo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5255', 'spa', 'Obediente, sumiso; dispuesto a obedecer y someterse a la autoridad o dirección recibida', 'Este adjetivo describe a quien escucha y obedece a otro, ya sea como cualidad de carácter (disposición obediente) o como condición (estar sujeto a una autoridad). En el griego clásico se aplicaba a súbditos obedientes a gobernantes, alumnos a maestros o fenómenos que respondían a leyes naturales. En el Nuevo Testamento se enfatiza la obediencia voluntaria como virtud, no como mero cumplimiento externo sino como genuina sumisión de la voluntad. Las tres apariciones involucran obediencia humana a Dios o al liderazgo designado por él.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5256', 'spa', 'Servir, ministrar, asistir; prestar servicio o ayuda, especialmente en capacidad oficial', 'Originalmente significaba servir como remero en un barco (de ὑπηρέτης, «remero subordinado»), pero pasó a designar el servicio en general, especialmente de carácter oficial o subordinado. Implica asistencia activa y ayuda práctica, no mera presencia. En el Nuevo Testamento abarca tanto el servicio cívico (atención y ayuda) como el servicio ministerial (apoyo práctico a la obra). El término sugiere un servicio organizado y con propósito, rendido a alguien o a una causa, frecuentemente con un matiz de subordinación hacia quien se sirve.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5257', 'spa', 'Asistente o funcionario subordinado; ya sea un oficial del templo o tribunal que ejecuta órdenes, o un servidor personal y ayudante ministerial. Deriv', 'Asistente o funcionario subordinado; ya sea un oficial del templo o tribunal que ejecuta órdenes, o un servidor personal y ayudante ministerial. Derivado del mundo del remo (hypo + eretes, ''remero de abajo''), ὑπηρέτης pasó a significar cualquier subordinado que sirve bajo autoridad. En los Evangelios, la palabra se refiere con mayor frecuencia a los oficiales y guardias del Sanedrín y los sumos sacerdotes, la policía del templo que arresta a Jesús (Jn 7:32), lo golpea durante su juicio (Mc 14:65) y se calienta junto a Pedro en el patio (Jn 18:18). Pero la misma palabra también describe a Juan Marcos sirviendo como ayudante de Pablo y Bernabé (Hch 13:5), al asistente de la sinagoga que recibe el rollo de manos de Jesús (Lc 4:20), e incluso a los apóstoles como servidores de Cristo (1 Co 4:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5258', 'spa', 'Hypnos -- sueño; descanso físico natural, a veces usado figuradamente para la modorra espiritual o la muerte.', 'El sustantivo hypnos (''sueño''), origen del castellano ''hipnosis'', designa el estado natural de descanso físico e inconsciencia. En el Nuevo Testamento aparece tanto en contextos literales como figurados. José despierta del sueño (hypnos) tras recibir el mensaje angélico sobre María (Mateo 1:24). Los discípulos están ''cargados de sueño'' en el Monte de la Transfiguración (Lucas 9:32). Jesús aclara que el ''sueño'' de Lázaro es en realidad muerte (Juan 11:13). El joven Eutico cae en ''sueño profundo'' (bathys hypnos) durante el extenso sermón de Pablo y se precipita desde el tercer piso (Hechos 20:9). Romanos 13:11 lo emplea metafóricamente: ''es hora de despertar del sueño''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5259', 'spa', 'Debajo de, por (agente); con genitivo marca el agente de una acción; con acusativo indica posición inferior o subordinación.', 'Ὑπό es una preposición cuyas dos caras principales — agencia y posición espacial — son tan distintas que muchas lenguas las separan por completo. Con genitivo (171 ocurrencias) señala al agente de un verbo pasivo: los profetas hablaron ''por'' el Espíritu Santo, Jesús fue bautizado ''por'' Juan, y la Escritura se cumplió según lo dicho ''por'' el Señor a través del profeta (Mt 1:22). Con acusativo (51 ocurrencias) pasa a lo espacial ''debajo de'': una lámpara puesta ''debajo de'' un almud, un centurión ''bajo'' autoridad, polluelos reunidos ''bajo'' las alas. El español ilustra perfectamente esta escisión — por para la agencia, bajo/debajo de para la posición. El raro uso temporal de Hch 5:21 (''hacia el amanecer'') muestra la preposición en el límite de su alcance.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5262', 'spa', 'Ejemplo, modelo o copia; abarca desde un paradigma moral propuesto para imitación o advertencia hasta una representación terrenal imperfecta de una realidad celestial.', 'Este sustantivo posee una doble fuerza en el Nuevo Testamento. Por un lado, designa un ejemplo o modelo que se presenta para imitación o advertencia: Cristo lavando los pies de los discípulos como patrón de servicio humilde (John 13:15), los profetas como ejemplos de paciencia (Jas 5:10), o Sodoma y Gomorra como advertencia del juicio divino (2 Pet 2:6). Por otro lado, Hebreos emplea la palabra para referirse al tabernáculo terrenal como mera copia o sombra de la realidad celestial (Heb 8:5; 9:23). La diferencia entre ambos sentidos es sutil pero real: uno apunta hacia adelante (''sigan este modelo''), el otro apunta hacia arriba (''esto es solo un bosquejo de lo verdadero'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5263', 'spa', 'Mostrar, demostrar o señalar; también advertir o prevenir a alguien sobre un peligro o juicio venidero.', 'Este verbo significa fundamentalmente hacer algo visible o evidente: mostrar, demostrar o señalar lo que antes era desconocido. Jesús dice a un discípulo ''yo os mostraré'' a quién temer (Luke 12:5) y Pablo relata que el Señor ''me mostró'' lo que debía padecer (Acts 9:16). Pero en boca de Juan el Bautista y de Jesús, adquiere un tono más incisivo: ''¿Quién os advirtió que huyerais de la ira venidera?'' (Matt 3:7; Luke 3:7). Aquí la palabra pasa de una demostración neutral a una amonestación urgente, transformando el simple mostrar en una advertencia solemne ante el juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5264', 'spa', 'Recibir como huésped, acoger en la propia casa; ofrecer hospitalidad albergando a alguien.', 'Conlleva la cálida connotación de dar la bienvenida a un huésped en la propia morada, yendo más allá del simple recibir para implicar hospitalidad personal. En Lucas 10:38 Marta «recibió» a Jesús en su casa, y en Lucas 19:6 Zaqueo lo «recibió» con gozo. Hechos 17:7 describe a Jasón acogiendo a Pablo y Silas en Tesalónica, y Santiago 2:25 recuerda a Rahab, quien «recibió» a los espías israelitas. En cada caso se destaca un anfitrión que asume riesgo o iniciativa personal al ofrecer refugio y bienvenida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5265', 'spa', 'Atar bajo los pies, calzar sandalias; sujetar el calzado con correas o tiras', 'Este verbo significa atar sandalias o zapatos a los pies, una acción necesaria ya que el calzado antiguo se aseguraba con correas en lugar de ser de ponerse directamente. El compuesto (ὑπό, «debajo» + δέω, «atar») captura la acción de sujetar las correas bajo y alrededor del pie. En voz pasiva significa «estar calzado» o «haberse puesto las sandalias». En el Nuevo Testamento aparece tanto en instrucciones literales sobre calzado para prepararse a viajar como en la metáfora de la armadura espiritual, donde los pies se «calzan» con la disposición del evangelio de paz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5266', 'spa', 'Sandalia, calzado — el calzado básico del antiguo Cercano Oriente; símbolo de humildad servil y tierra sagrada. El sustantivo ὑπόδημα (hypodema) desig', 'Sandalia, calzado — el calzado básico del antiguo Cercano Oriente; símbolo de humildad servil y tierra sagrada. El sustantivo ὑπόδημα (hypodema) designa una sandalia o zapato, el calzado estándar del mundo bíblico. Su peso teológico supera con creces su humilde forma material. Juan el Bautista se declara indigno de ''llevar'' o ''desatar'' las sandalias del que viene (Mt 3:11; Mc 1:7; Lc 3:16; Jn 1:27; Hch 13:25), ya que quitar las sandalias era la tarea del esclavo más bajo. Jesús envía a los Doce sin sandalias de repuesto (Mt 10:10; Lc 10:4), simbolizando una dependencia radical de Dios. Ante la zarza ardiente, se le ordena a Moisés quitarse las sandalias en tierra santa (Hch 7:33, haciéndose eco de Éx 3:5). Al hijo pródigo se le ponen sandalias como señal de restauración filial (Lc 15:22).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5270', 'spa', 'Debajo de, bajo, por debajo — preposición espacial que indica posición inferior a algo, frecuentemente con fuerza metafórica. La preposición impropia ', 'Debajo de, bajo, por debajo — preposición espacial que indica posición inferior a algo, frecuentemente con fuerza metafórica. La preposición impropia ὑποκάτω (hypokatō) significa ''debajo de, bajo, por debajo'', combinando ὑπό con κάτω para dar énfasis. Su uso teológicamente más significativo proviene del Salmo 110:1: Dios pondrá a los enemigos del Mesías como ''estrado debajo de sus pies'' (Mt 22:44; Mc 12:36; Heb 2:8). La mujer sirofenicia suplica que ''aun los perros debajo de la mesa comen las migajas de los hijos'' (Mc 7:28). Jesús instruye a los discípulos a sacudir el polvo de ''debajo de sus pies'' (Mc 6:11), y Lucas señala que nadie pone una lámpara ''debajo de la cama'' (Lc 8:16). En Apocalipsis, las almas claman desde ''debajo del altar'' (Ap 6:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5272', 'spa', 'ὑπόκρισις — hipocresía, fingimiento, simulación; representar un papel que no se habita genuinamente.', 'Enraizado en el mundo teatral — ὑπόκρισις significaba originalmente ''representar un papel en el escenario'' (de ὑποκρίνομαι, ''responder, actuar un rol'') — este sustantivo pasó a designar el vicio moral de aparentar ser lo que no se es. Jesús lo emplea como crítica demoledora contra los líderes religiosos que ejecutan piedad sin transformación interior: ''También vosotros por fuera parecéis justos, pero por dentro estáis llenos de hipocresía e iniquidad'' (Matt 23:28). Lucas 12:1 advierte contra ''la levadura de los fariseos, que es la hipocresía''. Pablo confronta la hipocresía de Pedro en Antioquía (Gal 2:13), y 1 Timothy 4:2 alerta sobre engañadores que hablan ''con hipocresía''. La metáfora teatral pervive en la raíz etimológica del español ''hipocresía''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5273', 'spa', 'Hipócrita, farsante: quien finge piedad o virtud careciendo de devoción genuina; un actor religioso. Ὑποκριτής significaba originalmente un actor de t', 'Hipócrita, farsante: quien finge piedad o virtud careciendo de devoción genuina; un actor religioso. Ὑποκριτής significaba originalmente un actor de teatro en el griego clásico — alguien que habla detrás de una máscara — pero para la época del Nuevo Testamento se había convertido en un epíteto punzante para los farsantes religiosos. Las 18 ocurrencias llevan este sentido peyorativo, y la gran mayoría provienen de labios de Jesús mismo en el Evangelio de Mateo, donde se convierte en su reproche característico a los escribas y fariseos. En el Sermón del Monte, Jesús advierte contra practicar la justicia ''como los hipócritas'' que oran en las esquinas y desfiguran sus rostros al ayunar para ser vistos (Mt 6:2, 5, 16). La devastadora séptuple ''¡Ay de vosotros, escribas y fariseos, hipócritas!'' de Mateo 23 (vv. 13, 15, 23, 25, 27, 29) constituye la denuncia más concentrada de los Evangelios. Lucas conserva a Jesús llamando hipócritas a las multitudes por leer las señales del clima pero no las señales de los tiempos (Lc 12:56; 13:15). La metáfora teatral subyacente — una persona representando un papel en vez de vivir con autenticidad — le da a la palabra su fuerza moral perdurable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5274', 'spa', 'ὑπολαμβάνω — recibir, acoger; suponer o asumir; responder en una conversación', 'El verbo ὑπολαμβάνω (literalmente ''tomar por debajo'') abarca un campo semántico sorprendentemente amplio en sus cinco apariciones neotestamentarias, que incluye sentidos físicos, cognitivos y conversacionales. Una nube ''recibió'' a Jesús en la Ascensión (Hch 1:9), Pedro ''respondió'' a una pregunta de Jesús en un diálogo (Lc 7:43; 10:30), Pedro dice a la multitud de Pentecostés que no ''supongan'' que los discípulos están ebrios (Hch 2:15), y Juan exhorta a los creyentes a ''acoger'' a los misioneros itinerantes (3 Jn 1:8). Esta amplitud semántica se refleja en español con recibir, suponer y responder, evidenciando tres dominios distintos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5278', 'spa', 'Quedarse atrás o permanecer; más frecuentemente, soportar con paciencia, perseverar bajo adversidad sin ceder. Compuesto de ὑπό (''debajo'') y μένω (''pe', 'Quedarse atrás o permanecer; más frecuentemente, soportar con paciencia, perseverar bajo adversidad sin ceder. Compuesto de ὑπό (''debajo'') y μένω (''permanecer''), este verbo retrata a alguien que se mantiene firme bajo una carga pesada en vez de huir. Su sentido dominante en el NT es la perseverancia firme — soportar persecución, sufrimiento o prueba sin desplomarse (Mt 10:22; He 12:2-3; Stg 5:11). Sin embargo, el significado espacial más antiguo del compuesto — ''quedarse atrás después de que otros se han ido'' — aparece dos veces: el niño Jesús quedándose en Jerusalén (Lc 2:43) y Silas permaneciendo en Berea cuando Pablo parte (Hch 17:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5279', 'spa', 'Recordar a alguien o traer algo a la memoria; en voz pasiva, ser recordado o acordarse de algo.', 'ὑπομιμνῄσκω se construye a partir de ὑπό (''debajo, desde abajo'') y μιμνῄσκω (''recordar''), sugiriendo un traer suavemente desde lo profundo de la memoria. En sus formas activas describe el acto deliberado de devolver algo a la atención de alguien, como cuando Jesús promete que el Espíritu les ''recordará todo lo que les he dicho'' (Jn 14:26), o cuando Pablo instruye a Tito a ''recordarles que se sujeten a los gobernantes'' (Tit 3:1). La única aparición pasiva en Lc 22:61 es conmovedora: Pedro ''se acordó'' de la palabra de Jesús al cantar el gallo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5280', 'spa', 'Recordatorio, remembranza; acto de traer algo a la memoria o mantenerlo presente en la mente', 'Este sustantivo designa el acto de recordar o el estado de tener algo presente en la memoria, frecuentemente con el matiz de mantener algo activo en la mente en lugar de dejarlo caer en el olvido. Platón llamó a la escritura un «fármaco de recordatorio» (ὑπόμνησις), algo que impulsa el recuerdo más que implanta el conocimiento. En el Nuevo Testamento refleja la preocupación pastoral por mantener las verdades importantes vivas y activas en la mente de los creyentes. Las tres apariciones se encuentran en 2 Timoteo y 2 Pedro, epístolas enfocadas en preservar la verdad apostólica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5281', 'spa', 'Perseverancia, resistencia paciente: permanecer firme bajo la prueba sin ceder, una virtud cristiana cardinal.', 'Perseverancia, resistencia paciente: permanecer firme bajo la prueba sin ceder, una virtud cristiana cardinal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5282', 'spa', 'Sospechar, suponer, conjeturar; formarse una opinión basada en evidencia parcial o suposición', 'Este verbo significa sospechar, conjeturar o suponer algo, es decir, formarse una opinión tentativa sin plena certeza. Puede tener connotaciones negativas (sospecha, desconfianza) o neutras (conjetura razonable). La raíz implica pensar por debajo de la superficie (ὑπό + νοέω), examinando posibilidades más allá de lo evidente. Sus tres apariciones en el Nuevo Testamento se encuentran en Hechos, describiendo interpretaciones inciertas de situaciones donde la información completa no está disponible. El término captura la naturaleza provisional del juicio humano cuando se trabaja con datos incompletos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5286', 'spa', 'Escabel o estrado; plataforma baja donde se apoyan los pies, usado principalmente como metáfora de la soberanía divina.', 'En el uso clásico designaba literalmente un mueble colocado bajo los pies, pero en el NT funciona casi exclusivamente como una metáfora teológicamente cargada tomada del Salmo 110:1 — ''hasta que ponga a tus enemigos por estrado de tus pies''. Esta imagen real, la cita veterotestamentaria más frecuente en el NT, representa la sujeción total de los enemigos bajo los pies del soberano. Aparece en el argumento de Jesús (Lc 20:43), en el sermón de Pedro en Pentecostés (Hch 2:35), en el discurso de Esteban citando a Isaías (Hch 7:49, ''la tierra es mi estrado''), y en la argumentación cristológica de Hebreos (He 1:13; 10:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5287', 'spa', 'ὑπόστασις — sustancia, esencia, realidad; certeza firme o fundamento seguro de la convicción', 'El sustantivo ὑπόστασις (literalmente ''lo que está debajo'') es una de las palabras de mayor peso teológico en el Nuevo Testamento, pues porta la fuerza de realidad subyacente y certeza firme. En Heb 1:3 el Hijo es la imagen exacta de la ὑπόστασις de Dios — su ser o esencia misma —, pasaje que se volvió fundacional para la teología trinitaria posterior. En Heb 11:1 la fe es la ὑπόστασις de lo que se espera, traducida como ''sustancia'', ''certeza'' o ''realidad firme''. Pablo la emplea en 2 Cor 9:4 y 11:17 con el sentido de ''confianza'' o ''base para gloriarse''. El término oscila entre dos polos: la realidad objetiva y la certidumbre subjetiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5288', 'spa', 'Retraerse, echarse atrás, rehuir; abstenerse de declarar o actuar algo por temor o cobardía.', 'Expresa la idea de retroceder, retraerse o guardar algo por timidez, frecuentemente con un matiz de cobardía o autoprotección. En Hechos 20:20 y 20:27, Pablo insiste en que no se retrajo de anunciar todo el consejo de Dios a los efesios. Gálatas 2:12 describe cómo Pedro se retraía de compartir la mesa con los gentiles cuando llegaron los del partido de la circuncisión. Hebreos 10:38 advierte que si alguien retrocede, el alma de Dios no se complace en esa persona. El término transmite un movimiento hacia atrás: una retirada de la convicción bajo presión social.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5290', 'spa', 'Regresar, volver: desplazamiento físico de retorno a un lugar previo; raramente, retroceder de un camino emprendido.', 'Regresar, volver: desplazamiento físico de retorno a un lugar previo; raramente, retroceder de un camino emprendido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5292', 'spa', 'Sumisión, sujeción, subordinación; el acto o la postura de colocarse bajo la autoridad de otro.', 'Designa el ordenamiento voluntario o esperado de una persona bajo una autoridad, ya sea divina, eclesial o doméstica. En 2 Corintios 9:13, Pablo elogia la sumisión de los corintios al evangelio, evidenciada por su generosidad. Gálatas 2:5 registra que Pablo se negó a ceder en sumisión a los falsos hermanos ni por una hora, protegiendo la libertad del evangelio. Primera Timoteo 2:11 y 3:4 lo emplean para el aprendizaje en quietud y la gestión del hogar respectivamente. El concepto describe una posición ordenada dentro de una jerarquía reconocida, no mera obediencia pasiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5293', 'spa', 'Poner bajo autoridad, sujetar, subordinar; en voz media/pasiva, someterse voluntariamente o ser sometido.', 'Poner bajo autoridad, sujetar, subordinar; en voz media/pasiva, someterse voluntariamente o ser sometido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5297', 'spa', 'Soportar, sobrellevar; resistir con paciencia una carga o dificultad sin ceder', 'Este verbo compuesto (ὑπό «debajo» + φέρω «llevar») significa cargar con un peso que se nos ha puesto encima, especialmente resistir o sobrellevar dificultades. La imagen es la de sostener desde abajo lo que nos presiona. El griego clásico lo usaba tanto para cargar peso literal como para la resistencia figurada ante adversidades. En el Nuevo Testamento se enfatiza la perseverancia paciente ante el sufrimiento, ya sea persecución o pruebas en general, sin derrumbarse ni abandonar la fe. Es una resistencia activa, no resignación pasiva: seguir cargando lo que se nos ha encomendado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5302', 'spa', 'Carecer, quedarse corto, padecer necesidad o agotarse; ser deficiente en lo que se necesita o espera, ya sea material o moralmente. Un verbo que descr', 'Carecer, quedarse corto, padecer necesidad o agotarse; ser deficiente en lo que se necesita o espera, ya sea material o moralmente. Un verbo que describe la insuficiencia en sus múltiples matices — desde carecer de algo específico, hasta no alcanzar un estándar, hasta padecer verdadera privación. Cuando Jesús pregunta a los discípulos en Lc 22:35 si les faltó algo en su misión, la palabra capta la ausencia de necesidades concretas. Pero en Ro 3:23, Pablo la eleva al plano moral: todos están destituidos de la gloria de Dios. En las bodas de Caná (Jn 2:3), la palabra describe el vino que se acabó físicamente — una provisión agotada — lo cual prepara el escenario para la primera señal de Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5303', 'spa', 'Carencia, deficiencia, falta; aquello que falta o queda corto, sea necesidad material o incompletitud espiritual.', 'Ὑστέρημα designa un déficit o carencia: la brecha entre lo que se tiene y lo que se necesita. Aparece tanto en contextos de pobreza material como de falta relacional o espiritual. La viuda pobre da de su ὑστέρημα, es decir, de su verdadera necesidad (Lc 21:4), mientras que Pablo habla de suplir lo que falta en el servicio de los corintios (1 Co 16:17; 2 Co 9:12) y del equilibrio recíproco entre abundancia y carencia (2 Co 8:14). El campo semántico se centra uniformemente en «aquello que todavía se necesita».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5305', 'spa', 'Después, luego, finalmente — adverbio temporal que marca una posición posterior o conclusiva en una secuencia de eventos. El adverbio ὕστερον (hystero', 'Después, luego, finalmente — adverbio temporal que marca una posición posterior o conclusiva en una secuencia de eventos. El adverbio ὕστερον (hysteron) señala lo que viene después, luego o al final de una secuencia. En las parábolas de Mateo estructura el clímax narrativo: el segundo hijo ''después'' se arrepintió y fue (Mt 21:29), los líderes religiosos no creyeron ''después'' (21:32), y ''por último'' el dueño envió a su hijo (21:37). Las vírgenes insensatas llegan ''después'' y encuentran la puerta cerrada (Mt 25:11), y dos falsos testigos se presentaron ''al final'' en el juicio de Jesús (Mt 26:60). La palabra frecuentemente conlleva una nota de finalidad u oportunidad perdida: lo que llega tarde puede llegar demasiado tarde.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5308', 'spa', 'Alto, elevado, encumbrado en el espacio; figuradamente orgulloso, altivo o arrogante en actitud.', 'Alto, elevado, encumbrado en el espacio; figuradamente orgulloso, altivo o arrogante en actitud.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5310', 'spa', 'Altísimo, como título divino; lo más alto, como superlativo de lugar o alabanza. El adjetivo superlativo ὕψιστος cumple dos funciones estrechamente re', 'Altísimo, como título divino; lo más alto, como superlativo de lugar o alabanza. El adjetivo superlativo ὕψιστος cumple dos funciones estrechamente relacionadas pero distinguibles en el NT. Como sustantivo con artículo, es uno de los grandes títulos divinos — ''el Altísimo'' (ὁ ὕψιστος) — empleado por ángeles, demonios y profetas para nombrar a Dios en su suprema exaltación. Gabriel anuncia que Jesús será llamado ''Hijo del Altísimo'' (Lucas 1:32), y el endemoniado gadareno clama ''Hijo del Dios Altísimo'' (Marcos 5:7). Como adjetivo en la frase doxológica ἐν τοῖς ὑψίστοις, designa los cielos ''más altos'' o el ámbito supremo de alabanza — ''¡Hosanna en las alturas!'' (Mateo 21:9) y ''Gloria a Dios en las alturas'' (Lucas 2:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5311', 'spa', 'Altura o lugar elevado, ya sea elevación espacial o exaltación metafórica que denota honor y posición distinguida.', 'En la mayoría de sus apariciones neotestamentarias, este sustantivo se refiere a la altura literal o a un lugar celestial elevado: el ''sol naciente desde lo alto'' que visita al pueblo de Dios (Luke 1:78), el poder ''desde lo alto'' en Pentecostés (Luke 24:49), las dimensiones inconmensurables del amor de Cristo incluyendo su altura (Eph 3:18), y Cristo ascendiendo ''a lo alto'' llevando cautiva la cautividad (Eph 4:8). Pero Santiago lo emplea de manera notablemente distinta: el hermano humilde debe ''gloriarse en su exaltación'' (Jas 1:9), donde la altura se convierte en metáfora de dignidad y honra. El español transita de ''altura'' y ''lo alto'' (elevación física) a ''exaltación'' (honor y dignidad).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5312', 'spa', 'Levantar, elevar, exaltar; físicamente de ser levantado en una cruz, y metafóricamente de ser elevado en honor o estatus. Ὑψόω es un verbo vertical — ', 'Levantar, elevar, exaltar; físicamente de ser levantado en una cruz, y metafóricamente de ser elevado en honor o estatus. Ὑψόω es un verbo vertical — siempre se mueve hacia arriba, ya sea física o metafóricamente. Juan lo usa con deliberado doble sentido para la crucifixión: ''como Moisés levantó la serpiente, así es necesario que el Hijo del Hombre sea levantado'' (Jn 3:14), donde la vergonzosa elevación en la cruz se convierte en el momento de la glorificación divina. Los Sinópticos prefieren el eje moral: ''el que se exalta será humillado'' (Mt 23:12; Lc 14:11; 18:14). Hechos proclama que Dios exaltó a Jesús a su diestra (Hch 2:33; 5:31). En todos sus usos, ὑψόω insiste en que la verdadera altura pertenece solo a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5315', 'spa', 'Comer, consumir alimento — forma aorista del verbo para comer, que abarca comidas literales, consumo figurado y banquetes escatológicos.', 'Φαγεῖν es el infinitivo aoristo (del verbo defectivo cuyo presente es ἐσθίω) usado a lo largo del Nuevo Testamento para el acto de comer. Aparece en relatos de comidas cotidianas, alimentaciones milagrosas (Mt 14:16, 20; 15:32-38), controversias sobre lo que es lícito comer (Mt 12:4; Mc 2:26) e invitaciones al banquete escatológico (''para que comáis y bebáis a mi mesa en mi reino'', Lc 22:30). El hecho de que Jesús comiera con pecadores y publicanos se convierte en sello distintivo de su ministerio (Mt 9:11; Lc 15:2). El español ''comer'' lo traduce de forma directa y natural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5316', 'spa', 'Brillar, dar luz; aparecer o hacerse visible; parecer o dar la impresión de.', 'Brillar, dar luz; aparecer o hacerse visible; parecer o dar la impresión de.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5318', 'spa', 'Visible, manifiesto, públicamente conocido; en Pablo, ''exterior'' en contraste con lo oculto o interior. Derivado del verbo φαίνω (''brillar, aparecer'')', 'Visible, manifiesto, públicamente conocido; en Pablo, ''exterior'' en contraste con lo oculto o interior. Derivado del verbo φαίνω (''brillar, aparecer''), φανερός describe lo que es claramente visible o públicamente conocido. Marcos lo usa para referirse a la fama de Jesús haciéndose ''manifiesta'' ante Herodes (Mc 6:14), y las parábolas sinópticas insisten en que nada oculto dejará de hacerse φανερόν (Mc 4:22; Lc 8:17). Pablo emplea la palabra extensamente — las obras de la carne son ''evidentes'' (Gá 5:19), y su encarcelamiento se ha hecho ''conocido'' en toda la guardia pretoriana (Fil 1:13). Un uso paulino distintivo en Ro 2:28 contrasta la judaidad ''exterior'' (ἐν τῷ φανερῷ) con la verdadera circuncisión del corazón, un matiz que el español capta como ''visible'' frente a la realidad más profunda y oculta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5319', 'spa', 'Manifestar, revelar, dar a conocer; aparecer visiblemente — de verdades, personas o propósitos divinos sacados a la luz', 'En el corazón de φανερόω está el movimiento de lo oculto a lo visible. Las formas pasivas predominan en el NT, describiendo cómo la justicia de Dios ha sido «manifestada» aparte de la ley (Ro 3:21) y cómo Cristo «apareció» a los discípulos tras la resurrección (Jn 21:14). La voz activa reserva la agencia para Dios o Cristo: Jesús «manifestó su gloria» en Caná (Jn 2:11) y «dio a conocer» el nombre del Padre (Jn 17:6). El español distingue con precisión «fue manifestado» (pasivo) de «manifesté» (activo), reflejando fielmente el contraste de voz del griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5320', 'spa', 'Abiertamente, claramente, de manera manifiesta; de modo visible, público o evidente', 'Este adverbio describe una acción realizada de forma abierta, pública o clara, en contraste con lo secreto o ambiguo. Enfatiza la visibilidad y la ausencia de ocultamiento. El adjetivo raíz φανερός significa «visible» o «manifiesto», relacionado con φαίνω («brillar», «aparecer»). La retórica antigua valoraba hablar φανερῶς, es decir, de forma clara y directa, en contraposición a los enigmas. En el Nuevo Testamento abarca tanto la visibilidad literal (aparecer en público) como la claridad epistemológica (ver con distinción, saber con certeza). El adverbio marca un contraste con lo oculto o lo oscuro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5328', 'spa', 'Φαραώ — Faraón, título real de los reyes del antiguo Egipto', 'Φαραώ es la forma griega indeclinable del hebreo פַּרְעֹה, derivado a su vez del egipcio pr-ꜥꜣ (''casa grande''), que se convirtió en el título estándar de los monarcas de Egipto. En el Nuevo Testamento se refiere específicamente al faraón innominado del relato del Éxodo. Aparece en el discurso de Esteban (Hch 7:10, 13, 21), en la exposición paulina sobre la soberanía divina al endurecer el corazón de Faraón (Ro 9:17), y en la descripción de la fe de Moisés al rechazar su condición de nieto adoptivo de Faraón (Heb 11:24). Prácticamente todas las lenguas preservan el título con grafía casi idéntica, reflejo de su reconocimiento universal como designación real histórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5329', 'spa', 'Fares, hijo de Judá y Tamar, antepasado del rey David y de Jesucristo', 'Fares (en hebreo פֶּרֶץ, que significa «brecha») nació de Judá y su nuera Tamar en uno de los relatos más escandalosos de Génesis (capítulo 38). A pesar de las circunstancias irregulares de su concepción, Fares se convirtió en un antepasado fundamental: la línea de David y, en última instancia, de Jesús pasó por él. Su nacimiento gemelar se caracterizó por irrumpir antes que su hermano Zera, de ahí su nombre. Rut 4:12 invoca su nombre como bendición de fecundidad. Las genealogías de Mateo y Lucas establecen la descendencia legal de Jesús a través de este eslabón decisivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5330', 'spa', 'Fariseo — miembro de la secta judía consagrada a la observancia rigurosa de la Torá, la tradición oral y la separación de la impureza ritual.', 'Φαρισαῖος aparece 99 veces en el Nuevo Testamento, lo que convierte a los fariseos en el grupo judío mencionado con mayor frecuencia en los Evangelios y Hechos. El nombre probablemente deriva del hebreo פָּרַשׁ (''separar''), reflejando su empeño en mantener fronteras rituales. Defendían la Torá oral junto a la escrita, creían en la resurrección y en los ángeles (Hch 23:8) y ejercían una notable influencia popular. Las controversias más intensas de Jesús son con los fariseos — sobre el sábado (Mt 12:2), el lavado de manos (Mt 15:2) y la acusación de hipocresía (Mt 23). Sin embargo, el retrato no es uniformemente hostil: Nicodemo es fariseo (Jn 3:1) y Pablo reivindica orgullosamente esa identidad (Fil 3:5; Hch 26:5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5332', 'spa', 'hechicero, envenenador; boticario, quien practica magia o prepara pociones', 'Originalmente designaba a quien mezclaba drogas o venenos, con frecuencia con fines dañinos. Con el tiempo, el término pasó a describir a practicantes de magia y hechicería. En los contextos bíblicos, se refiere consistentemente a quienes se involucran en prácticas ocultas, manipulando fuerzas espirituales mediante pociones, conjuros o encantamientos. La palabra conlleva connotaciones fuertemente negativas, asociando a tales practicantes con el engaño y la rebelión contra Dios. El uso en Apocalipsis refleja la difusa frontera del mundo antiguo entre la farmacología y lo oculto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5333', 'spa', 'Hechicero, envenenador, mago; quien practica artes ocultas o usa drogas y pociones con fines mágicos', 'El término φάρμακος (raíz de nuestras palabras «farmacia» y «farmacéutico») originalmente designaba a quien usaba drogas o pociones, lo cual en el mundo antiguo frecuentemente incluía a envenenadores o practicantes de artes mágicas mediante hierbas y compuestos. La frontera entre medicina, veneno y magia era difusa en la antigüedad. Para la época del Nuevo Testamento, el término designaba claramente a los practicantes de artes ocultas, es decir, hechiceros. Sus tres apariciones se encuentran en las listas de vicios de Apocalipsis, donde los hechiceros se agrupan con los inmorales, homicidas, idólatras y mentirosos: aquellos excluidos de la nueva Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5335', 'spa', 'Afirmar, aseverar, declarar; sostener algo como cierto con confianza y firmeza', 'Este verbo significa afirmar, aseverar o declarar, es decir, hacer una afirmación con cierto grado de fuerza. Aunque es similar al verbo común φημί ("decir"), φάσκω conlleva un matiz de mayor énfasis, sugiriendo una declaración segura o una pretensión. En el griego clásico se distinguía como un habla más contundente o enfática. Sus escasos usos en el Nuevo Testamento lo muestran describiendo afirmaciones enérgicas, ya sean veraces (como las de los acusadores de Pablo) o falsas (como quienes pretenden ser sabios mientras se vuelven necios). Señala un discurso que toma postura, no que meramente informa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5336', 'spa', 'Pesebre o comedero para ganado; la cuna improvisada donde fue acostado el niño Jesús.', 'Designa un comedero o pesebre utilizado para contener forraje para animales domésticos como bueyes o asnos. En el griego clásico, el término podía extenderse a cualquier establo o lugar de alimentación. El uso neotestamentario se centra en el relato lucano de la natividad, donde el pesebre se convierte en la humilde cuna del Mesías (Lucas 2:7, 12, 16), y en el argumento de Jesús sobre el sábado, donde incluso un buey o asno atado es desatado de su pesebre para darle de beber (Lucas 13:15). El término subraya la humildad concreta de la encarnación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5337', 'spa', 'φαῦλος — malo, vil, moralmente perverso; describe acciones o carácter de baja calidad moral.', 'En el griego clásico, φαῦλος podía significar ''barato, trivial, fácil'' — un juicio meramente cuantitativo de insignificancia. Sin embargo, en el período koiné y especialmente en el Nuevo Testamento, la palabra se ha desplazado decisivamente hacia la evaluación moral: ''malo, perverso, vil''. Jesús contrasta a quienes hicieron lo bueno (τὰ ἀγαθά) con quienes practicaron lo malo (τὰ φαῦλα) en el juicio de la resurrección (John 5:29). John 3:20 advierte que ''todo el que practica lo malo odia la luz''. Pablo invoca la misma polaridad moral en Romans 9:11 y 2 Corinthians 5:10, y Titus 2:8 exige una conducta que no deje a los adversarios ''nada malo que decir''. El español ''malo'' y ''vil'' convergen en el sentido de maldad moral sin ambigüedad residual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5338', 'spa', 'Luz, resplandor, brillo; la cualidad luminosa o esplendor que emana de una fuente', 'Este sustantivo designa la luz, especialmente el resplandor o la radiancia, es decir, el brillo que emana de cuerpos celestes u otras fuentes luminosas. Puede referirse a la luz del día, la luz de la luna o la cualidad luminosa de objetos brillantes. En el griego clásico se distinguía φέγγος (luz como radiancia) de φῶς (luz como sustancia o fuente), aunque ambos términos se solapan. En el Nuevo Testamento aparece principalmente en contextos apocalípticos que describen el oscurecimiento de las luminarias celestes: el sol y la luna dejando de dar su resplandor, señalando el fin del orden presente y la llegada de la presencia directa de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5339', 'spa', 'Perdonar, abstenerse de dañar — contenerse de infligir castigo, pérdida o severidad. El verbo φείδομαι (pheidomai) significa ''perdonar'' o ''abstenerse ', 'Perdonar, abstenerse de dañar — contenerse de infligir castigo, pérdida o severidad. El verbo φείδομαι (pheidomai) significa ''perdonar'' o ''abstenerse de dañar'', y aparece siempre en voz media en el NT. Su uso teológicamente más significativo se encuentra en Romanos 8:32: Dios ''no escatimó a su propio Hijo'', un eco deliberado de la narrativa de Abraham e Isaac (Gn 22:12, 16 LXX usa el mismo verbo). Pablo advierte que lobos feroces no ''perdonarán'' al rebaño (Hch 20:29), y recuerda a los corintios que vino con gentileza para ''perdonarlos'' (2 Co 1:23; 13:2). El argumento de Romanos 11:21 se construye sobre el hecho de que Dios no perdonó a las ramas naturales del olivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5342', 'spa', 'Llevar, traer, cargar; trasladar objetos, dar fruto, transportar físicamente, ser impulsado por una fuerza, soportar', 'φέρω es uno de los verbos más antiguos del griego, emparentado con el latín ferre, el inglés bear y el sánscrito bharati. Su amplitud en el NT refleja esa honda raigambre: desde traer a un paralítico en una camilla (Lc 5:18) hasta la metáfora agrícola de llevar fruto (Jn 15:2), pasando por un barco impulsado por el viento (Hch 27:15) y la capacidad de soportar circunstancias difíciles (Ro 9:22). La envergadura del término refleja el patrón teológico del discipulado: hay que cargar la cruz y, al mismo tiempo, dar fruto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5343', 'spa', 'Huir o escapar de un peligro o amenaza; en sentido raro, escapar con éxito, enfatizando el resultado.', 'Huir o escapar de un peligro o amenaza; en sentido raro, escapar con éxito, enfatizando el resultado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5344', 'spa', 'Félix; procurador romano de Judea ante quien fue juzgado el apóstol Pablo (ca. 52-59 d.C.).', 'Félix es el cognomen latino (que significa «feliz, afortunado») de Antonio Félix, el procurador romano de Judea que presidió el juicio de Pablo en Cesarea. Las nueve apariciones en el NT se concentran en Hechos 23-25, donde Félix recibe a Pablo del tribuno Claudio Lisias (Hch 23:24, 26), escucha la acusación presentada por Tértulo (Hch 24:3), conversa en privado con Pablo sobre la justicia y el dominio propio (Hch 24:24-25), y finalmente deja a Pablo preso como favor a los líderes judíos (Hch 24:27). El nombre se transliterá de forma consistente en todos los idiomas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5346', 'spa', 'φημί — decir, declarar, afirmar; verbo introductorio del discurso directo usado en todas las personas y tiempos', 'El verbo φημί («yo digo») es uno de los verbos de habla más antiguos y elementales del griego, y funciona principalmente como marco narrativo para introducir el discurso directo. En el Nuevo Testamento dominan sus formas de tercera persona del singular, φησί y ἔφη, que sirven como escuetas acotaciones de diálogo: «dijo». Aparece en intercambios dialógicos rápidos: Jesús respondiendo a sus acusadores (Mt 26:34, 61), Pilato interrogando a Jesús (Mt 27:11, 23) y Pablo testificando ante Festo y Agripa (Hch 25:22; 26:1, 24-25). A diferencia de λέγω, que puede portar matices de discurso razonado, φημί es un performativo puro de enunciación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5347', 'spa', 'Festo — Porcio Festo, el procurador romano de Judea que sucedió a Félix. Φῆστος (Porcio Festo) aparece 13 veces en los últimos capítulos de Hechos, to', 'Festo — Porcio Festo, el procurador romano de Judea que sucedió a Félix. Φῆστος (Porcio Festo) aparece 13 veces en los últimos capítulos de Hechos, todas dentro de la narrativa de los procedimientos legales de Pablo en Cesarea. Festo sucedió a Félix como procurador de Judea alrededor del año 59 d.C. y heredó el caso de Pablo. Lucas lo retrata como un administrador más competente que su predecesor, aunque igualmente enredado políticamente — dispuesto a usar a Pablo como gesto diplomático hacia los líderes judíos (Hechos 25:9). Su dramático intercambio con Pablo (''¡Estás loco, Pablo!'' Hechos 26:24) ofrece uno de los momentos judiciales más memorables del Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5348', 'spa', 'Llegar a, alcanzar o arribar a un destino o estado; en el uso clásico, preceder o anticipar.', 'φθάνω posee una fascinante historia semántica. En el griego clásico significaba principalmente ''llegar antes, adelantarse, anticipar'' — la urgencia de llegar primero. Sin embargo, en la koiné la connotación competitiva se suavizó hacia la simple llegada: ''alcanzar, llegar, arribar''. La mayoría de los usos neotestamentarios refleja este desarrollo posterior. Cuando Jesús dice ''el reino de Dios ha llegado a vosotros'' (Mt 12:28; Lc 11:20), la fuerza es de llegada y presencia, no de prioridad. No obstante, en 1 Ts 4:15 resurge el sentido antiguo: los vivos ''de ninguna manera precederemos'' a los muertos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5349', 'spa', 'Perecedero, corruptible; sujeto a descomposición y destrucción, describiendo la naturaleza transitoria de lo terrenal y material.', 'Derivado de φθείρω (''destruir, corromper''), este adjetivo señala algo sujeto a deterioro y disolución. Pablo contrasta φθαρτός de manera tajante con lo imperecedero (ἄφθαρτος) en 1 Corintios 15:53-54, donde los cuerpos mortales deben ''revestirse'' de incorrupción. En Romanos 1:23 expone lo absurdo de cambiar la gloria del Dios inmortal por imágenes de criaturas perecederas. La evidencia multilingüe es notablemente uniforme: español corruptible, francés périssable, alemán vergänglich, todos convergiendo en un único sentido de transitoriedad frente a la permanencia divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5350', 'spa', 'Hablar, pronunciar, emitir sonido; producir habla articulada o sonido vocal', 'Este verbo significa hablar, pronunciar o emitir un sonido articulado. A diferencia de los verbos más comunes para «decir» o «hablar», φθέγγομαι pone énfasis en el acto físico de producir sonido vocal, ya sea habla humana o incluso la voz de un animal. En el Nuevo Testamento aparece en contextos donde la emisión de la voz misma resulta notable: el Sanedrín prohíbe a Pedro y Juan «hablar» en el nombre de Jesús, la burra de Balaam «habló» con voz humana para reprender al profeta, y los falsos maestros «pronuncian» palabras arrogantes y vacías. El verbo subraya la acción sonora del habla más que su contenido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5351', 'spa', 'Corromper, arruinar o destruir; deterioro moral, contaminación del carácter o la mente, o ruina física como juicio divino.', 'Verbo poderoso que abarca desde la corrupción moral hasta la destrucción total. Pablo advierte que «las malas compañías corrompen las buenas costumbres» (1 Co 15:33) y que el viejo hombre «se va corrompiendo» por los deseos engañosos (Ef 4:22), reflejando ambos usos un deterioro moral progresivo. Pero la misma palabra también denota ruina catastrófica: Dios «destruirá» a quien profane su templo (1 Co 3:17), y los falsos maestros «perecen» como animales irracionales (2 P 2:12). El español distingue bien ambos polos con «corromper» para la degradación moral y «destruir» para la aniquilación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5355', 'spa', 'Envidia, celos, malquerencia; deseo resentido provocado por la ventaja ajena, frecuentemente listado entre los vicios.', 'Φθόνος describe la emoción amarga de la envidia: un resentimiento hostil hacia quienes poseen lo que uno desea. En el griego clásico se oponía tanto a la buena voluntad (εὔνοια) como al elogio (ἔπαινος), y el Nuevo Testamento conserva esa fuerte carga negativa. Aparece en catálogos de vicios junto al homicidio, la contienda y el engaño (Ro 1:29; Gá 5:21; 1 Ti 6:4; Tit 3:3) y se identifica como el motivo detrás de la entrega de Jesús a Pilato (Mt 27:18; Mr 15:10). Pablo también señala que algunos predican a Cristo «por envidia y rivalidad» (Fil 1:15). La envidia se presenta consistentemente como una emoción corrosiva y destructiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5356', 'spa', 'Corrupción, deterioro, destrucción; el estado de lo perecedero o la ruina moral, y el proceso activo de ser destruido.', 'Forma sustantiva de φθείρω (G5351), que abarca todo el espectro desde lo perecedero hasta la destrucción activa. Pablo contrasta lo que se siembra «en corrupción» con lo que resucita «en incorrupción» (1 Co 15:42), y advierte que la carne y la sangre no pueden heredar el reino porque pertenecen al ámbito de φθορά (1 Co 15:50). En 2 Pedro, el término se intensifica hacia la destrucción activa: los falsos maestros prometen libertad, pero son ellos mismos «esclavos de la corrupción» (2 P 2:19), y los creyentes son llamados a escapar de «la corrupción que hay en el mundo por la concupiscencia» (2 P 1:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5357', 'spa', 'φιάλη — copa, vaso de libación; una copa ancha y poco profunda, especialmente las copas de oro de la ira en Apocalipsis. El sustantivo φιάλη (''copa, v', 'φιάλη — copa, vaso de libación; una copa ancha y poco profunda, especialmente las copas de oro de la ira en Apocalipsis. El sustantivo φιάλη (''copa, vaso de libación'') designa una copa ancha y poco profunda originalmente asociada con las ofrendas de libación en la práctica religiosa griega. En el uso clásico era el recipiente estándar para verter libaciones a los dioses. El Nuevo Testamento confina todas las doce ocurrencias al libro de Apocalipsis, donde las copas cumplen dos funciones simbólicas: en Apocalipsis 5:8, los veinticuatro ancianos sostienen copas de oro ''llenas de incienso, que son las oraciones de los santos''; y predominantemente, las siete copas de oro de la ira de Dios son derramadas sobre la tierra en una devastadora secuencia de juicios (Ap 15:7; 16:1-4, 8, 10, 12, 17; 17:1; 21:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5360', 'spa', 'Amor fraternal; el afecto cálido y cuidado mutuo compartido entre miembros de una comunidad espiritual o familiar.', 'Φιλαδελφία significa literalmente ''amor de hermanos'' (φίλος + ἀδελφός), y en el Nuevo Testamento designa la calidez distintiva que los creyentes deben manifestar unos hacia otros como miembros de la familia de Dios. Romanos 12:10 exhorta a los cristianos a ser devotos mutuamente en φιλαδελφία, mientras que 2 Pedro 1:7 la sitúa como la penúltima virtud antes del ἀγάπη en una cadena de crecimiento espiritual. Las traducciones son sumamente consistentes: español amor fraternal, francés amour fraternel, alemán Bruderliebe, todas reflejando un afecto entre hermanos que se extiende más allá de los lazos de sangre hacia la familia de la fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5368', 'spa', 'Amar con afecto personal o cariño; besar como saludo o señal de intimidad.', 'Amar con afecto personal o cariño; besar como saludo o señal de intimidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5370', 'spa', 'Un beso; acto de presionar los labios sobre otra persona, usado como saludo, señal de amor o expresión litúrgica de comunión.', 'Denota el acto físico de besar, que tenía profundo significado social y religioso en el mundo antiguo. En los Evangelios, el beso aparece en dos escenas radicalmente opuestas: los besos llorosos y amorosos de la mujer pecadora sobre los pies de Jesús (Lc 7:45), y el beso de traición de Judas (Lc 22:48) — el mismo gesto con significados contrarios. Pablo transforma luego el beso en práctica litúrgica, instruyendo cuatro veces a los creyentes a saludarse con un ''ósculo santo'' (Ro 16:16; 1 Co 16:20; 2 Co 13:12; 1 Ts 5:26). El español distingue entre ''beso'' (beso común) y ''ósculo'' (beso más solemne y sagrado), reflejando el paso del gesto social a la práctica de adoración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5375', 'spa', 'Filipos, importante colonia romana en Macedonia; lugar de la primera iglesia europea fundada por Pablo.', 'Nombre de una ciudad prominente en la provincia romana de Macedonia, originalmente llamada Crenides y renombrada por Filipo II de Macedonia. Como colonia romana gozaba del estatus cívico especial de ius Italicum. Pablo fundó allí su primera congregación europea tras su visión del varón macedonio (Hechos 16:12), y su carta a los filipenses sigue siendo una de las epístolas más personales y gozosas. La forma plural Φίλιπποι refleja una convención griega habitual para nombres de ciudades.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5376', 'spa', 'Felipe: nombre griego que significa ''amante de los caballos'', llevado por el apóstol, el evangelista y los tetracas herodianos.', 'Felipe: nombre griego que significa ''amante de los caballos'', llevado por el apóstol, el evangelista y los tetracas herodianos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5382', 'spa', 'Hospitalario, dado a la hospitalidad; que ama y acoge a extraños y huéspedes', 'Este adjetivo describe a quien ama a los extraños (de φίλος, «que ama», y ξένος, «extraño/huésped»). En el mundo antiguo, donde las posadas eran escasas y a menudo de mala fama, la hospitalidad resultaba esencial para los viajeros, especialmente para los misioneros y maestros cristianos itinerantes. La hospitalidad no era mera cortesía, sino un deber moral y religioso que demostraba el amor en acción. Las tres apariciones en el Nuevo Testamento figuran en listas de requisitos para líderes eclesiales o de virtudes cristianas generales, mostrando que acoger a los extraños es marca de liderazgo cristiano maduro y de verdadero discipulado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5384', 'spa', 'Amigo, compañero querido — alguien unido por afecto y lealtad, no solo por parentesco.', 'Amigo, compañero querido — alguien unido por afecto y lealtad, no solo por parentesco.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5389', 'spa', 'Aspirar, ambicionar, proponerse como meta; buscar con empeño un objetivo digno', 'Este verbo compuesto (de φίλος, «que ama», y τιμή, «honor») significaba originalmente amar el honor o ser ambicioso. Puede ser neutro (tener ambición, perseguir una meta) o negativo (buscar vanagloria). Sin embargo, los usos en el Nuevo Testamento son enteramente positivos: una determinación apasionada por alcanzar metas espirituales dignas. Pablo lo emplea para describir sus aspiraciones misioneras y su propósito de agradar al Señor. Expresa una ambición santa que canaliza el impulso del logro hacia fines que honran a Dios en vez de buscar gloria propia. La vida cristiana implica una búsqueda apasionada, no una deriva pasiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5391', 'spa', 'benévolo, amigable; que muestra calidez y buena voluntad hacia los demás', 'Este adjetivo describe una disposición marcada por calidez genuina y amabilidad, del tipo que se refleja en el rostro y en la manera de saludar. Los escritores antiguos lo empleaban para quienes recibían a sus huéspedes con gracia, miraban a otros con bondad y estaban dispuestos a tratar a las personas con generosa buena voluntad. La forma adverbial aparece frecuentemente en contextos de recepción hospitalaria: saludar con afecto, dar la bienvenida con auténtica amabilidad en lugar de fría formalidad. Capta tanto la actitud interior como su expresión exterior en un comportamiento cordial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5392', 'spa', 'Amordazar, silenciar, hacer callar; usado literalmente para sujetar a un animal y figuradamente para silenciar personas o fuerzas.', 'Φιμόω significaba originalmente amordazar a un animal, y el NT conserva este sentido concreto al citar Deuteronomio 25:4 sobre no poner bozal al buey (1 Co 9:9; 1 Ti 5:18). De manera mucho más dramática, Jesús emplea la palabra para silenciar a un demonio (Mr 1:25), reprender a una tormenta (Mr 4:39), y sus adversarios quedan «amordazados» sin poder replicar (Mt 22:34). Las traducciones al español revelan la distinción: «pondrás bozal» para el sentido literal, frente a «Cállate» y «Enmudece» para el figurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5395', 'spa', 'Llama o fuego ardiente; combustión visible usada en teofanías, juicio escatológico y el tormento del más allá.', 'Se refiere a la parte visible y luminosa del fuego —la llama misma— que porta un profundo peso teológico en el NT. Aparece en contextos teofánicos donde Dios se manifiesta mediante fuego: la zarza ardiente donde un ángel se presenta ''en llama de fuego'' (Hch 7:30) y la descripción de los ángeles como ''llamas de fuego'' (Heb 1:7). También señala el juicio escatológico, como cuando el Señor Jesús se revela ''en llama de fuego'' (2 Ts 1:8) y sus ojos son ''como llama de fuego'' (Ap 1:14). En Lucas 16:24, nombra el fuego atormentador del Hades.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5398', 'spa', 'temible, terrible; que causa temor o pavor, o digno de reverente temor', 'Este adjetivo describe algo que inspira temor, ya sea terror (algo espantoso) o reverencia (algo digno de respeto sobrecogedor). La raíz φόβος puede significar tanto pavor como reverencia. Las tres apariciones en el Nuevo Testamento se encuentran en Hebreos, describiendo realidades sobrecogedoras en relación con Dios: la expectativa del juicio, caer en sus manos, y la reacción de Moisés ante la teofanía del Sinaí. No se trata de miedos irracionales, sino de respuestas apropiadas ante la santidad y el juicio divinos. El término capta la gravedad y el peso de encontrarse con el Dios vivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5399', 'spa', 'Temer, tener miedo; reverenciar o sentir temor reverente de Dios; abarca el terror ante el peligro y el asombro ante lo divino', 'El temor en las Escrituras nunca es una sola emoción. Este verbo recorre todo el espectro: desde el terror visceral de los discípulos en la tormenta (Mt 14:26) hasta el temor reverente que caracteriza la verdadera adoración (Lc 1:50, «Su misericordia es para los que le temen»). La forma deponente pasiva (φοβέομαι) convierte al que teme en sujeto gramatical de una experiencia que lo sobrecoge. Hechos 10 lo emplea tres veces de Cornelio, el temeroso de Dios, donde «temer a Dios» funciona prácticamente como término técnico de devoción gentil. El español capta la amplitud con «temieron» (terror) junto a «temed» (reverenciad).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5401', 'spa', 'Temor, espanto, reverencia: la emoción de alarma ante el peligro o de asombro reverente ante lo divino.', 'Temor, espanto, reverencia: la emoción de alarma ante el peligro o de asombro reverente ante lo divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5403', 'spa', 'Fenicia, región costera al norte de Palestina a lo largo del Mediterráneo oriental', 'Fenicia era el nombre antiguo de la franja costera del actual Líbano y el norte de Israel, hogar de pueblos navegantes famosos por su comercio, la púrpura y el desarrollo del alfabeto. Sus ciudades principales incluían Tiro y Sidón. Aunque predominantemente gentil, la región tenía vínculos históricos con Israel y aparece en el ministerio de Jesús con la mujer sirofenicia. En Hechos, Fenicia cobra importancia en la expansión geográfica de la iglesia primitiva, cuando creyentes dispersos por la persecución llevan el evangelio hacia el norte por la costa, extendiendo la misión más allá de Jerusalén y Judea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5406', 'spa', 'Asesino, homicida; quien quita la vida humana de manera ilícita, tanto en sentido literal como de perseguidores de los justos.', 'Designa a una persona que quita la vida a otra de manera ilícita: un asesino u homicida. En el NT aparece en contextos que van desde la retribución real (Mt 22:7, el rey que destruye a los homicidas que mataron a sus siervos) hasta la acusación profética (Hch 7:52, donde Esteban denuncia al Sanedrín como ''traidores y homicidas'' del Justo). En Hechos 28:4, los isleños paganos suponen que Pablo debe ser un asesino cuando una víbora se le prende de la mano, y en 1 Pedro 4:15 se advierte a los cristianos que ninguno padezca como homicida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5407', 'spa', 'φονεύω — asesinar, cometer homicidio ilícito; el verbo detrás de la prohibición del Sexto Mandamiento. El verbo φονεύω (''cometer asesinato'') denota la', 'φονεύω — asesinar, cometer homicidio ilícito; el verbo detrás de la prohibición del Sexto Mandamiento. El verbo φονεύω (''cometer asesinato'') denota la toma ilícita y deliberada de la vida humana, distinguida en el pensamiento moral griego del homicidio lícito en guerra. Su perfil neotestamentario está moldeado por el Decálogo: ''No matarás'' (Mateo 5:21; 19:18; Marcos 10:19; Lucas 18:20; Romanos 13:9; Santiago 2:11). Jesús profundiza el mandamiento en el Sermón del Monte, declarando que la ira misma hace al hombre ''reo de juicio'' tal como lo es el homicida (Mateo 5:21-22). Santiago lo despliega en aguda crítica social — ''Matáis y codiciáis'' (Santiago 4:2) — y ''habéis condenado y dado muerte al justo'' (Santiago 5:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5408', 'spa', 'Homicidio, asesinato, matanza; la privación violenta e ilícita de la vida humana.', 'Φόνος designa el acto de homicidio o matanza violenta. Derivado de la raíz presente en θείνω («golpear»), conlleva el peso del derramamiento de sangre deliberado e ilícito. Jesús lo enumera entre los males que brotan del corazón (Mt 15:19; Mr 7:21), y Lucas lo emplea para describir el crimen de Barrabás (Lc 23:19, 25; Mr 15:7). Aparece en catálogos de vicios junto a la contienda y el engaño (Ro 1:29) y entre los pecados que los impenitentes se niegan a abandonar (Ap 9:21).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5409', 'spa', 'Llevar o portar habitualmente; forma frecuentativa de φέρω que indica acción repetida o característica de cargar o vestir.', 'Φορέω es la forma frecuentativa de φέρω (''llevar, cargar''), enfatizando una acción habitual o característica más que un acto aislado. En Mateo 11:8 Jesús pregunta si salieron a ver a un hombre vestido con ropas delicadas, mientras que en Juan 19:5 Pilato presenta a Jesús llevando la corona de espinas, un acto momentáneo cargado de peso simbólico. Pablo emplea φορέω de manera poderosa en 1 Corintios 15:49: así como hemos llevado la imagen del hombre terrenal, llevaremos también la imagen del celestial. El español llevar y el alemán tragen captan con naturalidad este sentido de ''portar sobre la persona''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5411', 'spa', 'φόρος — tributo, impuesto; pago obligatorio exigido por una autoridad gobernante a sus súbditos', 'φόρος designa un tributo o impuesto recaudado por un poder gobernante, derivado de φέρω (''llevar, traer''), es decir, literalmente ''lo que se aporta''. En el Nuevo Testamento aparece cinco veces, siempre en contextos que discuten la legitimidad y la obligación de pagar impuestos a Roma. El célebre intercambio de Jesús sobre el tributo al César (Lc 20:22) y la acusación ante Pilato de que lo prohibía (Lc 23:2) enmarcan la tensión política, mientras que Pablo en Romanos 13:6-7 fundamenta el pago de impuestos en la obligación teológica hacia la autoridad divinamente establecida. El español ''tributo'' conserva la conexión con el latín tributum, subrayando el contexto imperial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5413', 'spa', 'Carga o peso que lleva una persona, ya sea literal o figurado; también la carga o mercancía de un barco.', 'En la mayoría de los casos este vocablo describe las cargas que llevan las personas: el yugo suave y la carga ligera que Jesús ofrece (Mateo 11:30), los pesados fardos que los fariseos atan sobre los hombros de los demás (Mateo 23:4; Lucas 11:46), y la carga personal que cada creyente debe llevar (Gálatas 6:5). Pero en Hechos 27:10 el sentido cambia hacia la carga de un barco amenazado por la tormenta, donde Pablo prevé la pérdida ''de la carga y del navío''. La evidencia multilingüe refleja bien la distinción: para cargas personales, el hindi usa ''bojh'' y el español ''cargas'', pero para el flete marítimo, el hindi cambia a ''maalke'' (bienes) y el inglés a cargo en lugar de burden.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5414', 'spa', 'carga, fardo, cargamento; peso literal o figurado de opresión y responsabilidad', 'Este término se refiere literalmente a la carga o mercancía transportada por barco o bestia de carga. Se extiende de manera natural a cargas metafóricas: el peso agobiante de responsabilidades, dificultades u obligaciones. Jesús emplea el diminutivo relacionado al prometer que su yugo es fácil y su carga ligera, contrastando con el peso aplastante del legalismo religioso. Pablo utiliza el lenguaje de carga para describir el peso del cuidado de las iglesias. El vocablo también puede denotar algo despreciable o sin valor, aunque este uso es menos relevante en los textos bíblicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5418', 'spa', 'Cerca, seto o muro divisorio; cualquier barrera que encierra, separa o divide.', 'Se refiere a una barrera construida, ya sea un seto alrededor de una viña, un muro junto a un camino, o una partición metafórica entre pueblos. En las parábolas de la viña, tanto Mateo 21:33 como Marcos 12:1 hacen eco de Isaías 5:2, donde el dueño edifica una cerca para proteger las vides. Lucas 14:23 sitúa a los pobres junto a los vallados y caminos rurales. El uso teológicamente más significativo aparece en Efesios 2:14, donde Cristo derriba el muro divisorio de hostilidad entre judío y gentil. El término abarca tanto lo físico como lo metafórico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5420', 'spa', 'tapar, bloquear, silenciar; cerrar o impedir el paso o el habla', 'Este verbo significa cercar, obstruir o detener, ya sea cerrando literalmente una abertura física o silenciando metafóricamente el habla o impidiendo una acción. El griego clásico lo empleaba para construir barreras, bloquear caminos o taponar heridas. Los usos neotestamentarios son metafóricos: callar bocas (silenciar), cerrar puertas a la crítica y cerrar las fauces de los leones. La forma pasiva indica ser detenido o silenciado por una fuerza externa. El término enfatiza la eficacia total del bloqueo: completamente cerrado, sin posibilidad de proceder ni hablar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5421', 'spa', 'Pozo, foso o cavidad; abertura excavada en la tierra para obtener agua o como cavidad profunda.', 'En griego, φρέαρ designa un pozo excavado o foso profundo, distinguido de un manantial natural (κρήνη). En los Evangelios aparece de forma concreta como el pozo donde Jesús se encuentra con la mujer samaritana (Jn 4:11-12), y en Lucas 14:5 como un pozo abierto en el que podría caer un animal. En Apocalipsis 9:1-2, el término adquiere una dimensión apocalíptica dramática como el ''pozo del abismo'', del cual brota humo demoníaco. El español ''pozo'' conserva el mismo doble alcance de fuente de agua y cavidad profunda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5426', 'spa', 'Pensar, tener una mentalidad, dirigir los pensamientos; abarca desde la reflexión momentánea hasta una disposición o actitud mental arraigada.', 'Pensar, tener una mentalidad, dirigir los pensamientos; abarca desde la reflexión momentánea hasta una disposición o actitud mental arraigada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5427', 'spa', 'Mentalidad, disposición interior de la mente; orientación arraigada del pensamiento hacia la carne o el Espíritu.', 'Sustantivo que designa la orientación estable y habitual de la mente, no un pensamiento pasajero sino una disposición profunda y duradera. Las cuatro apariciones en el NT se concentran en Romanos 8, donde Pablo contrasta la mentalidad de la carne (que conduce a la muerte) con la mentalidad del Espíritu (que produce vida y paz). En el griego clásico la palabra denotaba resolución o altivez, pero Pablo la restringe a la orientación mental profunda que determina la trayectoria de vida de una persona.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5429', 'spa', 'Sabio, prudente o astuto; que posee discernimiento práctico para tomar decisiones acertadas, a veces con connotaciones de astucia. φρόνιμος describe a', 'Sabio, prudente o astuto; que posee discernimiento práctico para tomar decisiones acertadas, a veces con connotaciones de astucia. φρόνιμος describe a alguien que piensa con claridad y actúa sabiamente en asuntos prácticos. Jesús lo usa repetidamente en parábolas para contrastar a quienes se preparan sabiamente con quienes no: el hombre prudente que edifica sobre roca (Mateo 7:24), las vírgenes prudentes que llevan aceite extra (Mateo 25:2, 4, 8, 9) y el mayordomo fiel (Mateo 24:45; Lucas 12:42). También lo elogia como cualidad para la misión, diciéndoles a los discípulos que sean ''prudentes como serpientes'' (Mateo 10:16). En un uso distintivo (Lucas 16:8), la palabra se desplaza hacia ''sagaz'' o ''astuto'', donde el administrador deshonesto es elogiado porque los ''hijos de este siglo'' son más φρόνιμοι que los ''hijos de la luz''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5432', 'spa', 'Guardar, custodiar, proteger; montar guardia militar o mantener bajo custodia protectora.', 'Término de origen militar que significa montar guardia, guarnecionar o mantener bajo vigilancia protectora. En el griego clásico describía a soldados patrullando un territorio o custodiando una fortaleza. Pablo lo usa para las tropas del gobernador que vigilaban Damasco para apresarlo (2 Co 11:32) y para la ley que mantenía a Israel bajo custodia antes de la fe (Gá 3:23). Filipenses 4:7 transforma bellamente la imagen militar: la paz de Dios guarnicionará vuestros corazones y mentes. Primera de Pedro 1:5 habla de los creyentes guardados por el poder de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5435', 'spa', 'Frigia, extensa región interior en el centro de Asia Menor', 'Frigia era un vasto territorio en el centro y occidente de Asia Menor (la actual Turquía), conocido por su riqueza agrícola y su población mixta de frigios autóctonos, griegos y judíos. Entre sus ciudades principales se contaban Laodicea, Colosas y Hierápolis. Sus fronteras variaron con el tiempo y en época romana quedó dividida entre varias provincias. Hechos menciona Frigia como parte de los viajes misioneros de Pablo, particularmente cuando fortalecía a los discípulos existentes. La presencia de frigios en Pentecostés (Hechos 2:10) indica una comunidad judía de la diáspora ya establecida allí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5438', 'spa', 'Guardia, vigilia nocturna, puesto de guardia, o (más frecuentemente en el NT) cárcel o lugar de reclusión.', 'Guardia, vigilia nocturna, puesto de guardia, o (más frecuentemente en el NT) cárcel o lugar de reclusión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5441', 'spa', 'guardias, centinelas; soldados asignados a vigilar y custodiar prisioneros o lugares', 'Este sustantivo designa a un guardia o centinela, especialmente un vigilante militar o carcelero. La forma plural se refiere a los guardias como grupo o al sistema de vigilancia. El griego clásico lo usaba para cualquier guardián o protector, pero en contextos helenísticos y romanos significaba comúnmente guardias militares. Todas las apariciones neotestamentarias están en Hechos, describiendo a los guardias de la prisión donde estaban retenidos los apóstoles. Los guardias representan el intento del poder terrenal de contener a los mensajeros de Dios, un esfuerzo que resulta inútil cuando los ángeles intervienen o los propósitos divinos requieren la liberación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5442', 'spa', 'Guardar, vigilar, observar mandamientos o guardarse de; abarca custodia física, obediencia moral, preservación divina y cautela vigilante.', 'Guardar, vigilar, observar mandamientos o guardarse de; abarca custodia física, obediencia moral, preservación divina y cautela vigilante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5443', 'spa', 'Tribu, clan: división de un pueblo por descendencia ancestral, especialmente las doce tribus de Israel.', 'Tribu, clan: división de un pueblo por descendencia ancestral, especialmente las doce tribus de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5444', 'spa', 'Hoja, hojas; el follaje de un árbol o planta, usado literal y como señal de cambio estacional o infructuosidad.', 'Φύλλον designa la hoja de un árbol o planta y aparece en los Evangelios principalmente en relación con la higuera. En Marcos 11:13 Jesús ve una higuera con hojas pero sin fruto, una imagen poderosa de apariencia exterior que encubre un vacío interior. El mismo vocablo aparece en el Discurso del Monte de los Olivos (Mateo 24:32, Marcos 13:28), donde las hojas que brotan señalan que el verano está cerca, una parábola de preparación escatológica. Todas las traducciones principales lo vierten de forma directa: español hojas, francés feuilles, alemán Blätter: hojas, sencillas y vívidas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5445', 'spa', 'φύραμα — masa (de harina); porción mezclada o amasada, usada literal y metafóricamente para una comunidad', 'φύραμα se refiere a una masa de harina amasada, del verbo φυράω (''mezclar, amasar''). Aunque la palabra tiene un origen culinario directo, todas sus apariciones neotestamentarias la emplean en sentido figurado. Pablo usa la masa del alfarero en Romanos 9:21 para argumentar el derecho soberano de Dios sobre su creación, mientras que en Romanos 11:16 las primicias consagradas santifican toda la masa. La metáfora de la levadura en 1 Corintios 5:6-7 y Gálatas 5:9 advierte que una pequeña porción de corrupción permea la comunidad entera. El español ''masa'' captura tanto el sentido literal como el figurado del término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5446', 'spa', 'Natural, innato, producido por la naturaleza; opuesto a lo artificial, enseñado o convencional', 'Este adjetivo griego describe lo que es natural o innato, en contraste con lo aprendido, enseñado o convencional. En Romanos 1:26-27, Pablo lo emplea para referirse al ''uso natural'' de la sexualidad humana, contrastándolo con lo que es ''contra naturaleza''. El término posee un peso filosófico significativo del griego clásico, donde distinguía entre lo que existe por naturaleza (φύσις) y lo que existe por convención (νόμος). En 2 Pedro 2:12, describe a criaturas que actúan de manera ''natural'' o instintiva, según su naturaleza creada y no por razonamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5448', 'spa', 'Hinchar de orgullo o vanidad; en voz pasiva, estar inflado de arrogancia. Término paulino para la soberbia espiritual.', 'φυσιόω deriva de φῦσα (''fuelle, soplo'') y evoca la imagen de algo que se infla como un globo, agrandándose más allá de su tamaño natural. Pablo se apropia casi exclusivamente de este verbo en el NT, empleándolo como diagnóstico certero de la enfermedad espiritual de Corinto. Seis de sus siete apariciones se hallan en 1 Corintios, donde el faccionalismo, la tolerancia de la inmoralidad y la jactancia intelectual se manifiestan como estar ''inflados''. El memorable contraste de 1 Corintios 8:1 —''el conocimiento envanece, pero el amor edifica''— opone la inflación a la construcción, la vanidad a la sustancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5449', 'spa', 'Naturaleza — el carácter inherente o constitución de una persona o cosa; también usado adverbialmente como ''por naturaleza'' para denotar lo que es inn', 'Naturaleza — el carácter inherente o constitución de una persona o cosa; también usado adverbialmente como ''por naturaleza'' para denotar lo que es innato. φύσις se refiere al orden natural, la constitución inherente o el carácter esencial de algo. Pablo lo usa extensamente en Romanos para discutir lo que concuerda con o viola la naturaleza (Romanos 1:26), lo que los gentiles incircuncisos hacen ''por naturaleza'' cuando siguen la ley escrita en sus corazones (Romanos 2:14, 27), y la metáfora de las ramas de olivo silvestre y cultivado y su relación natural versus injertada (Romanos 11:21, 24). La palabra también aborda identidad y origen: los judíos son ''por naturaleza'' judíos y no pecadores gentiles (Gálatas 2:15), los antiguos paganos servían a seres que ''por naturaleza'' no son dioses (Gálatas 4:8), y todos eran ''por naturaleza'' hijos de ira (Efesios 2:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5452', 'spa', 'Plantar — poner en la tierra para que crezca; en sentido figurado, establecer o fundar una comunidad espiritual. El verbo φυτεύω (phyteuō) significa c', 'Plantar — poner en la tierra para que crezca; en sentido figurado, establecer o fundar una comunidad espiritual. El verbo φυτεύω (phyteuō) significa colocar una planta en el suelo, y se usa tanto en sentido literal como figurado. La parábola de la viña de Jesús comienza con un hombre que ''plantó una viña'' (Mt 21:33; Mr 12:1), y una higuera está ''plantada'' en Lc 13:6. Jesús advierte que toda planta que su Padre ''no ha plantado será arrancada'' (Mt 15:13). Pablo emplea la metáfora para el ministerio apostólico: ''Yo planté, Apolos regó, pero Dios dio el crecimiento'' (1 Co 3:6-8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5453', 'spa', 'Brotar, crecer, germinar; dicho de plantas que nacen o surgen de la tierra', 'Este verbo griego describe el proceso natural de crecimiento y germinación, especialmente de las plantas. En la parábola del sembrador de Lucas (8:6, 8), representa las semillas que ''brotaron'' al ser sembradas, una imagen agrícola vívida y familiar para los oyentes de Jesús. La palabra enfatiza el proceso orgánico desde la semilla hasta la planta visible. En Hebreos 12:15, aparece en sentido metafórico: vigilar con cuidado ''no sea que alguna raíz de amargura, brotando, cause problema''. El participio perfecto expresa el estado de haber crecido o haber brotado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5455', 'spa', 'Llamar, convocar, gritar; del gallo, cantar', 'Llamar, convocar, gritar; del gallo, cantar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5456', 'spa', 'Voz, sonido vocal o emisión hablada; rara vez, un sonido no vocal o ruido de instrumentos o la naturaleza.', 'Una de las palabras sensoriales más vívidas del Nuevo Testamento, φωνή cubre toda la gama de expresión audible, desde la voz humana hasta las proclamaciones celestiales. Es el vocablo elegido para la voz divina en el bautismo de Jesús (''Este es mi Hijo amado'', Mt 3:17) y en la transfiguración, para Juan el Bautista como ''la voz que clama en el desierto'', y para los gritos de demonios, multitudes y ángeles en Apocalipsis. La evidencia interlingüística es notablemente estable: español ''voz'', francés ''voix'', alemán ''Stimme''. En dos casos excepcionales (1 Co 14:10; Ap 8:13), φωνή se extiende a sonidos no vocales, donde el español cambia a ''sonidos'', marcando la ampliación semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5457', 'spa', 'Luz; iluminación natural, divina o metafórica; raramente el resplandor de un fuego', 'Uno de los términos teológicos más ricos del Nuevo Testamento, φῶς abarca todo el espectro de la iluminación: desde la luz física del sol (Mt 17:2) hasta la luz divina que resplandece en las tinieblas (Jn 1:5) y la luz moral que los creyentes están llamados a encarnar (Mt 5:14). La declaración de Jesús «Yo soy la luz del mundo» (Jn 8:12) convierte esta palabra en piedra angular de la teología joánica. Una sola aparición en Marcos 14:54 se refiere específicamente al resplandor de una fogata en el patio, donde el campo semántico se estrecha hacia el fuego como fuente luminosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5460', 'spa', 'luminoso, brillante, lleno de luz — que irradia resplandor físico o espiritual', 'φωτεινός describe algo que está lleno de luz o que la irradia, derivado de φώς (‘luz’). En el Nuevo Testamento posee una doble dimensión: literal y espiritual-moral. La nube resplandeciente de la Transfiguración (Mt 17:5) representa su sentido físico más concreto, mientras que la enseñanza de Jesús sobre el ojo como lámpara del cuerpo (Mt 6:22; Lc 11:34, 36) emplea el término para describir la condición interior de quien posee una visión espiritual clara y sin corrupción. El español ‘luminoso’ refleja bien este doble registro de resplandor físico y claridad metafórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5461', 'spa', 'Iluminar, dar luz; alumbrar espiritualmente; sacar a la luz cosas ocultas, revelar. Derivado de φῶς (luz), este verbo abarca desde la iluminación físi', 'Iluminar, dar luz; alumbrar espiritualmente; sacar a la luz cosas ocultas, revelar. Derivado de φῶς (luz), este verbo abarca desde la iluminación física hasta la iluminación espiritual y la revelación. Juan 1:9 declara que la luz verdadera ''alumbra'' a todo ser humano que viene al mundo, una afirmación sobre la iluminación espiritual universal. En Apocalipsis, el mismo verbo describe la gloria de Dios iluminando literalmente la ciudad celestial (21:23) y al ángel cuyo esplendor ilumina toda la tierra (18:1). Pablo emplea una tercera dimensión: sacar a la ''luz'' lo oculto, ya sean los designios secretos de Dios en el día final (1 Co 4:5) o el misterio del plan de Cristo ahora revelado (Ef 3:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5463', 'spa', 'Regocijarse, alegrarse, gozarse; también saludo convencional que significa «¡salve!» o «¡saludos!»', 'Χαίρω es el verbo griego fundamental del gozo, que exhorta a los creyentes a regocijarse incluso en medio del sufrimiento (Mt 5:12; Fil 4:4). Desde la alegría personal hasta la celebración cósmica, aparece en contextos que van del gran gozo de los magos ante la estrella (Mt 2:10) a la exhortación paulina «estad siempre gozosos» (1 Ts 5:16). La forma imperativa también se cristalizó como saludo convencional — «¡Salve!» o «¡Saludos!» — usado tanto con sinceridad (el ángel a María, Lc 1:28) como en burla cruel (los soldados a Jesús, Mt 27:29). El español capta esta doble naturaleza con «alegraos/gozaos» para el gozo y «Salve» para el saludo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5464', 'spa', 'Granizo; piedras de granizo enviadas como juicio divino en visiones apocalípticas.', 'Designa el granizo o las piedras de granizo, un fenómeno natural que en las Escrituras funciona consistentemente como instrumento de juicio divino. Las cuatro apariciones en el NT se encuentran en Apocalipsis, evocando la plaga de granizo sobre Egipto (Éxodo 9:18-26) y las tradiciones teofánicas del Antiguo Testamento. En Apocalipsis 8:7 granizo mezclado con fuego y sangre devasta la tierra; en 11:19 un gran granizo acompaña la apertura del templo de Dios en el cielo; y en 16:21 enormes piedras de granizo de aproximadamente un talento de peso caen sobre los rebeldes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5465', 'spa', 'Bajar, descender mediante cuerda o mecanismo; soltar o arriar hacia abajo.', 'El verbo χαλάω significa bajar o descender algo soltando una cuerda o cabo. Aparece en escenas vívidas del NT: los amigos que bajan a un paralítico por un agujero en el techo (Mr 2:4), Pedro que echa las redes al mar por mandato de Jesús (Lc 5:4-5) y los discípulos que descienden a Pablo en una canasta por una abertura en la muralla para escapar de Damasco (Hch 9:25). En Hechos 27:17, los marineros arrían el ancla flotante durante una tormenta. El término siempre denota un movimiento controlado hacia abajo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5475', 'spa', 'cobre, bronce o latón — metal base y, por extensión, monedas u objetos fabricados con él', 'χαλκός designaba originalmente el cobre, el primer metal que el ser humano aprendió a fundir, y por extensión las aleaciones de bronce derivadas de él. Sus cinco apariciones en el Nuevo Testamento abarcan un abanico sorprendente: Jesús prohíbe a sus discípulos llevar monedas de cobre en el cinturón (Mt 10:9; Mc 6:8), Marcos describe las monedas de bronce echadas en el arca del templo (Mc 12:41), Pablo compara el discurso sin amor con un gong de bronce que retañe (1 Co 13:1) y Apocalipsis enumera el bronce entre las mercancías de lujo de Babilonia (Ap 18:12). El español ‘cobre/bronce’ refleja bien la doble identidad de este material.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5479', 'spa', 'Gozo, alegría, deleite — felicidad profunda arraigada en los actos salvíficos de Dios, el evangelio o la presencia del Espíritu', 'Χαρά es el sustantivo griego para el gozo, derivado de la misma raíz que χαίρειν («regocijaos»). En el Nuevo Testamento posee un color marcadamente teológico: es la respuesta al anuncio angélico del nacimiento de Jesús (Mt 2:10, «un gozo muy grande»), el fruto inmediato de recibir el evangelio (Mt 13:20, 44) y un sello distintivo de la vida en el Espíritu (Ga 5:22). Jesús habla de que su propio gozo sea cumplido en sus discípulos (Jn 15:11; 17:13), y Pablo exhorta al gozo aun en medio del sufrimiento (Fil 1:4, 25). La palabra también describe la recompensa escatológica: «Entra en el gozo de tu señor» (Mt 25:21, 23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5480', 'spa', 'Marca, sello, grabado; en Apocalipsis, la marca escatológica de la Bestia; en Hechos, producto de la artesanía humana.', 'Χάραγμα designa cualquier marca que se graba, se estampa o se imprime sobre una superficie. Siete de sus ocho apariciones en el NT se encuentran en Apocalipsis, donde se refiere a la siniestra marca de la Bestia impuesta en la mano derecha o en la frente como señal de lealtad (Ap 13:16-17). El único uso fuera de Apocalipsis (Hch 17:29) apunta a la artesanía: Pablo dice a los atenienses que la naturaleza divina no debe compararse con un grabado producto del arte y la imaginación humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5483', 'spa', 'Perdonar o indultar; dar generosamente o conceder como regalo; entregar o poner en manos de otro.', 'Perdonar o indultar; dar generosamente o conceder como regalo; entregar o poner en manos de otro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5484', 'spa', 'A causa de, por causa de, en favor de; preposición impropia que expresa causa o propósito.', 'Χάριν es el acusativo de χάρις («gracia, favor») fosilizado como preposición impropia con el significado de «a causa de», «por causa de» o «en favor de». Rige genitivo y expresa tanto la causa como el propósito detrás de una acción. Pablo lo emplea para explicar por qué fue dada la ley: «a causa de las transgresiones» (Gá 3:19), y para introducir la razón de su encarcelamiento: «por causa de vosotros los gentiles» (Ef 3:1, 14). Su alcance también cubre la causalidad simple, como en «porque sus muchos pecados le son perdonados» (Lc 7:47).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5485', 'spa', 'Gracia, favor o bondad — especialmente el favor inmerecido de Dios hacia la humanidad; también gratitud, acto concreto de buena voluntad o don.', 'Una de las palabras teológicamente más ricas del Nuevo Testamento, χάρις abarca desde la gracia divina que salva a los pecadores hasta la simple cortesía humana de dar las gracias. En su núcleo reside la idea de generosidad inmerecida — el favor pródigo de Dios derramado sobre quienes no tienen derecho alguno a reclamarlo (Jn 1:16; Ef 2:8). Pablo articula epístolas enteras en torno a esta palabra, y cada carta paulina se abre o se cierra con ella. Sin embargo, χάρις también cubre la gratitud cotidiana (Lc 6:32-34, ''¿qué mérito tenéis?''), actos concretos de favor político (Hch 24:27) e incluso una colecta monetaria para los pobres (1 Co 16:3). El español distingue ''gracia'' de ''gratitud''; el alemán traduce uniformemente Gnade, fusionando sentidos que el griego mantiene fluidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5486', 'spa', 'Don gratuito otorgado libremente por Dios, especialmente dotaciones espirituales para el servicio y el don de la salvación. Construido sobre la raíz χ', 'Don gratuito otorgado libremente por Dios, especialmente dotaciones espirituales para el servicio y el don de la salvación. Construido sobre la raíz χάρις (gracia), χάρισμα designa algo dado libre y generosamente por Dios. Pablo lo emplea a lo largo de un espectro notable: el don de la vida eterna contrastado con la paga del pecado (Ro 6:23), los dones y el llamamiento irrevocables de Israel (Ro 11:29), y los diversos dones espirituales distribuidos al cuerpo de Cristo — profecía, sanidad, lenguas, enseñanza (1 Co 12:4-11, 28-31; Ro 12:6). Cada χάρισμα es la gracia hecha concreta en una capacidad particular para el ministerio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5491', 'spa', 'Labio; por extensión, la orilla o ribera de un cuerpo de agua — reflejando la antigua metáfora del ''labio'' de la tierra junto al mar.', 'En su sentido primario, χεῖλος se refiere a los labios físicos de la boca, el órgano del habla y la adoración. La Septuaginta y el Nuevo Testamento lo emplean de manera prominente en contextos de alabanza e hipocresía: Jesús cita a Isaías en Mateo 15:8 y Marcos 7:6, advirtiendo que el pueblo honra a Dios ''con sus labios'' mientras su corazón está lejos. Pablo cita el Salmo 140:3 en Romanos 3:13, describiendo labios que ocultan veneno. Sin embargo, en Hebreos 11:12, χεῖλος pasa a significar ''orilla'' o ''borde'', describiendo descendientes tan innumerables como los granos de arena a la orilla del mar — una metáfora espacial enraizada en la idea de un límite semejante a un labio donde la tierra se encuentra con el agua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5494', 'spa', 'Invierno como estación fría del año; también tempestad o tormenta violenta, especialmente en el mar.', 'Esta palabra griega abarca dos realidades meteorológicas distintas. En cuatro apariciones significa invierno: la estación fría sobre la cual Jesús advierte en el Discurso del Olivar (Matt 24:20; Mark 13:18), el marco invernal de la Fiesta de la Dedicación (John 10:22) y la petición de Pablo a Timoteo de llegar antes del invierno (2 Tim 4:21). Pero en dos pasajes designa una tormenta violenta: el cielo rojo que presagia mal tiempo (Matt 16:3) y la tempestad que azotó el barco de Pablo (Acts 27:20). La evidencia multilingüe confirma la división: español usa «invierno» para la estación y «tempestad» para la tormenta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5495', 'spa', 'Mano, manos — la parte del cuerpo, expresando también agencia, poder, custodia y acción divina.', 'El griego χείρ (''mano'') despliega un abanico enorme de usos en el Nuevo Testamento, desde lo concretamente físico hasta lo profundamente metafórico. Jesús sana mediante la imposición de manos (Mc 6:5), lava metafóricamente las manos de sus discípulos a través del lavamiento de pies (Jn 13) y muestra sus manos traspasadas como prueba de la resurrección (Lc 24:40). ''La mano del Señor'' denota poder y acción divinos (Hch 11:21). Idiomáticamente, ser entregado ''en manos de'' alguien significa caer bajo su poder (Mt 17:22). El español ''manos'', el francés ''main'' y el alemán ''Hand'' reflejan el mismo espectro de lo literal a lo figurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5499', 'spa', 'Hecho a mano, manufacturado por esfuerzo humano; a menudo contrastado con la creación divina o espiritual.', 'Este adjetivo compuesto (de χείρ, «mano», y ποιέω, «hacer») describe cualquier cosa fabricada por la destreza humana. En el Nuevo Testamento casi siempre conlleva una connotación negativa o limitante: Dios no habita en templos hechos a mano (Acts 7:48; 17:24), y Cristo entró en un santuario no hecho por manos humanas (Heb 9:11). Mark 14:58 registra la falsa acusación de que Jesús destruiría el templo hecho a mano y edificaría otro «no hecho de mano». En Eph 2:11, la circuncisión se describe como «hecha en la carne por manos», relativizándola frente a una realidad espiritual mayor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5501', 'spa', 'Peor — adjetivo comparativo que denota una condición inferior, mayor severidad o deterioro moral. El adjetivo χείρων (cheirōn), comparativo irregular ', 'Peor — adjetivo comparativo que denota una condición inferior, mayor severidad o deterioro moral. El adjetivo χείρων (cheirōn), comparativo irregular de κακός (''malo''), describe un estado deteriorado o más severo. La condición del endemoniado re-poseído es ''peor que la primera'' (Mt 12:45; Lc 11:26), y la mujer con hemorragia ''empeoró'' bajo muchos médicos (Mr 5:26). Un remiendo sin encoger hace el desgarro ''peor'' (Mt 9:16; Mr 2:21). Pilato teme un ''peor'' engaño (Mt 27:64). Pedro advierte que los apóstatas encuentran su último estado ''peor'' (2 P 2:20), y Pablo dice que los impostores van ''de mal en peor'' (2 Ti 3:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5503', 'spa', 'viuda — mujer cuyo esposo ha muerto, frecuentemente emblema de vulnerabilidad y dependencia de la justicia de Dios', 'viuda — mujer cuyo esposo ha muerto, frecuentemente emblema de vulnerabilidad y dependencia de la justicia de Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5504', 'spa', 'Ayer; el día anterior al presente', 'Un adverbio temporal sencillo que significa ''ayer'', empleado en contextos que contrastan eventos recientes con el presente o el futuro. En Juan 4:52, el oficial pregunta a qué hora comenzó a mejorar su hijo, y los siervos responden: ''Ayer a la hora séptima''. Hechos 7:28 recuerda la acción de Moisés el día anterior: ''¿Acaso quieres matarme como mataste al egipcio ayer?''. Hebreos 13:8 lo emplea en la célebre fórmula ''Jesucristo es el mismo ayer, hoy y por los siglos'', abarcando pasado, presente y futuro. La palabra es cognada del latín ''heri'' y del sánscrito ''hyas''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5505', 'spa', 'mil; unidad de mil, usada para números grandes en contextos narrativos y apocalípticos', 'mil; unidad de mil, usada para números grandes en contextos narrativos y apocalípticos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5506', 'spa', 'quiliarca (comandante de mil); tribuno militar romano responsable de una cohorte de guarnición', 'quiliarca (comandante de mil); tribuno militar romano responsable de una cohorte de guarnición');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5507', 'spa', 'Mil — el número cardinal 1.000, usado literal y simbólicamente para duración y medida vastas. El adjetivo χίλιοι (chilioi) es el cardinal griego para ', 'Mil — el número cardinal 1.000, usado literal y simbólicamente para duración y medida vastas. El adjetivo χίλιοι (chilioi) es el cardinal griego para mil. Su uso en el NT se concentra en Apocalipsis con un rico peso simbólico. Pedro relativiza el tiempo humano: ''para el Señor un día es como mil años'' (2 P 3:8). Apocalipsis lo emplea para la duración del testimonio profético (Ap 11:3), el refugio de la mujer en el desierto (Ap 12:6), una gran distancia (Ap 14:20), y más célebremente el reinado milenario, donde Satanás es atado y los santos reinan por ''mil años'' (Ap 20:2-7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5509', 'spa', 'Tunica, prenda interior -- la vestidura basica que se llevaba directamente sobre la piel, distinta del manto exterior (ἱμάτιον). El sustantivo χιτών (', 'Tunica, prenda interior -- la vestidura basica que se llevaba directamente sobre la piel, distinta del manto exterior (ἱμάτιον). El sustantivo χιτών (chiton) designa la tunica que se vestia pegada al cuerpo. Jesus ensena una generosidad radical: no niegues tu tunica a quien te demanda el manto (Mt 5:40; Lc 6:29). Los misioneros no deben llevar una de repuesto (Mt 10:10; Mc 6:9). Juan el Bautista exige compartir las tunicas con los necesitados (Lc 3:11). El sumo sacerdote rasga sus vestiduras en el juicio de Jesus (Mc 14:63), y las amigas de Tabita muestran las tunicas que ella cosio para las viudas (Hch 9:39).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5515', 'spa', 'Verde, verde pálido o ceniciento; describe el color de la vegetación viva o la palidez cadavérica.', 'Adjetivo que abarca el espectro cromático desde el verde fresco hasta el pálido enfermizo, un continuo que el griego antiguo percibía como un solo matiz verdoso claro. En Marcos 6:39 Jesús sienta a la multitud sobre la hierba verde, evocando la exuberante primavera galilea. En Apocalipsis 9:4 se prohíbe a las langostas dañar toda cosa verde. Pero en Apocalipsis 6:8 el cuarto jinete monta un caballo χλωρός, con el tono verdoso y cadavérico de un cuerpo sin vida. El español capta esta dualidad con verde para la vegetación y verde pálido para la palidez mortuoria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5516', 'spa', 'seiscientos sesenta y seis (o seiscientos dieciséis), el número críptico de la bestia', 'Esta expresión numérica aparece únicamente en Apocalipsis 13:18 como el misterioso número de la bestia, uno de los símbolos más debatidos de la Escritura. Los manuscritos antiguos varían entre 666 y 616, lo cual sugiere que algunos copistas reconocían el número como un cifrado. Los lectores judíos y cristianos primitivos familiarizados con la gematría (donde las letras poseen valores numéricos) lo habrían entendido como una referencia codificada, posiblemente a un emperador romano. La triple repetición del seis, que no alcanza el siete perfecto, puede simbolizar la imperfección humana persistente y la rebelión contra Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5517', 'spa', 'Hecho de polvo, terrenal; relativo a la naturaleza material y mortal del ser humano formado del suelo.', 'Adjetivo derivado de χοῦς (polvo, tierra), que describe lo que está hecho de tierra o pertenece al ámbito del polvo. Pablo lo usa exclusivamente en 1 Corintios 15:47-49 para contrastar al primer Adán, que es terrenal —formado del suelo (Gn 2:7)— con el segundo Adán (Cristo), que es del cielo. Los creyentes actualmente llevan la imagen del hombre terrenal, pero llevarán la imagen del celestial. Esta polaridad entre lo terrenal y lo celestial estructura el argumento paulino sobre la resurrección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5519', 'spa', 'χοῖρος — cerdo, puerco; animal impuro según la ley mosaica, asociado con la impureza y la vida gentil. El sustantivo χοῖρος (''cerdo, puerco'') designa ', 'χοῖρος — cerdo, puerco; animal impuro según la ley mosaica, asociado con la impureza y la vida gentil. El sustantivo χοῖρος (''cerdo, puerco'') designa al cerdo doméstico, un animal clasificado como ritualmente impuro bajo las leyes alimentarias levíticas (Levítico 11:7). En el Nuevo Testamento cada ocurrencia lleva connotaciones de impureza, degradación o el mundo gentil. El episodio de los endemoniados gadarenos, donde Jesús envía demonios a una piara de cerdos que se precipitan al mar (Mateo 8:30-32; Marcos 5:11-13; Lucas 8:32-33), dramatiza la transferencia de impureza de las personas poseídas a animales ritualmente impuros. El punto más bajo del hijo pródigo es apacentar cerdos (Lucas 15:15-16), la ocupación más baja concebible para un joven judío. El proverbio de Jesús ''no echéis vuestras perlas delante de los cerdos'' (Mateo 7:6) usa χοῖρος como figura de quienes no pueden apreciar lo santo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5526', 'spa', 'Alimentar, llenar o saciar con comida; en voz pasiva, comer hasta quedar satisfecho. Originalmente un término para alimentar ganado, este verbo descri', 'Alimentar, llenar o saciar con comida; en voz pasiva, comer hasta quedar satisfecho. Originalmente un término para alimentar ganado, este verbo describe en el NT la experiencia profundamente satisfactoria de ser llenado con alimento — tanto físico como espiritual. Los milagros de alimentación (Mateo 14:20; 15:37; Marcos 6:42; 8:8) culminan todos con la multitud ''saciada'', y las Bienaventuranzas prometen que los que tienen hambre de justicia ''serán saciados'' (Mateo 5:6). La forma transitiva aparece cuando los discípulos se preguntan cómo podrían ''saciar'' a semejante multitud en el desierto (Mateo 15:33; Marcos 8:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5528', 'spa', 'Hierba, vegetación verde o pasto; también heno o hierba seca como metáfora de construcción. La palabra común para hierba y plantas verdes, que aparece', 'Hierba, vegetación verde o pasto; también heno o hierba seca como metáfora de construcción. La palabra común para hierba y plantas verdes, que aparece en la enseñanza de Jesús sobre el cuidado de Dios por la creación — si Dios así viste la hierba del campo, que hoy está viva y mañana se echa al horno, ¿cuánto más os vestirá a vosotros? (Mateo 6:30; Lucas 12:28). También marca la alfombra verde donde se sentaron los cinco mil (Marcos 6:39). En un uso distintivo, Pablo enumera el ''heno'' entre los materiales de construcción perecederos que no sobrevivirán la prueba del fuego (1 Corintios 3:12). El español distingue ''hierba'' (pasto vivo) de ''heno'' (hierba seca), confirmando claramente esta división semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5530', 'spa', 'Usar, hacer uso de, emplear; tambien tratar o relacionarse con alguien de una manera determinada. Verbo versatil en voz media que abarca tanto el empl', 'Usar, hacer uso de, emplear; tambien tratar o relacionarse con alguien de una manera determinada. Verbo versatil en voz media que abarca tanto el empleo practico de cosas como la manera de tratar a las personas. Pablo lo utiliza repetidamente al hablar de los derechos apostolicos, preguntando si ha ''hecho uso'' de su autoridad (1 Co 9:12, 15) o exhortando a los creyentes a ''usar'' el mundo sin dejarse absorber por el (1 Co 9:18; 1 Co 7:31). En Hch 27:17 los marineros ''usan'' cables de refuerzo para cenir la nave. Un sentido interpersonal mas sutil aparece en Hch 27:3, donde el centurion Julio ''trato'' a Pablo con amabilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5532', 'spa', 'Necesidad, carencia — estado de requerir lo que falta, o el servicio/tarea que debe cumplirse', 'Χρεία designa la condición de necesitar algo — ya sea espiritual, físico o práctico — y, por extensión, aquello que se necesita o el servicio que se presta. Jesús declara que «los sanos no tienen necesidad de médico» (Mt 9:12), el Padre «sabe lo que necesitáis antes de que se lo pidáis» (Mt 6:8), y la iglesia primitiva repartía «según cada uno tenía necesidad» (Hch 2:45; 4:35). Pablo amplía el término hacia la teología de la interdependencia dentro del cuerpo de Cristo: «el ojo no puede decir a la mano: No te necesito» (1 Co 12:21). En ocasiones χρεία se acerca a «tarea» o «servicio»: el Señor «tiene necesidad» del pollino (Mt 21:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5535', 'spa', 'necesitar, tener necesidad de, requerir — expresar carencia o necesidad', 'χρήζω expresa el estado de necesitar o requerir algo, construido sobre el impersonal χρή (‘es necesario’). En la enseñanza de Jesús aparece en su promesa tranquilizadora de que el Padre ya sabe lo que sus seguidores necesitan antes de que lo pidan (Mt 6:32; Lc 12:30), eliminando la ansiedad de la ecuación de la provisión divina. Lucas lo usa para describir la necesidad urgente de un vecino a medianoche (Lc 11:8). Pablo lo emplea al encomendar a Febe, pidiendo a la iglesia de Roma que la asistan en cualquier asunto que necesite (Ro 16:2), y al preguntar retóricamente si acaso necesita cartas de recomendación (2 Co 3:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5536', 'spa', 'Dinero, riquezas, bienes — posesiones medidas en valor monetario, desde propiedades hasta la moneda misma.', 'El término χρῆμα deriva de χράομαι (''usar, necesitar'') y originalmente significaba ''aquello que se necesita''. En el Nuevo Testamento, su plural χρήματα denota consistentemente dinero o riquezas. La palabra aparece en dos contextos distintos pero relacionados: transacciones financieras concretas y enseñanzas sobre el peligro espiritual de la riqueza. En Hechos, describe dinero real — el producto de la venta del campo de Bernabé (4:37) y el intento de Simón el Mago de comprar el Espíritu Santo (8:18-20). En los Evangelios Sinópticos, Jesús lo utiliza en su solemne declaración sobre cuán difícil es para los que tienen riquezas entrar en el reino de Dios (Marcos 10:23-24; Lucas 18:24).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5537', 'spa', 'Advertir o instruir por revelación divina; también, ser llamado o designado públicamente con un nombre o título.', 'Un verbo notablemente versátil cuyos dos sentidos neotestamentarios parecen muy distantes entre sí, aunque ambos se originan en una comunicación oficial y autoritativa. En su uso bíblico principal, Dios ''advierte divinamente'' o ''revela'' algo a una persona: los magos son advertidos en un sueño que no regresen a Herodes (Mt 2:12), y Moisés es instruido al construir el tabernáculo (Heb 8:5). El segundo sentido, ''ser llamado'' o ''llevar un nombre'', aparece cuando los discípulos son llamados por primera vez cristianos en Antioquía (Hch 11:26) y cuando una mujer que se casa de nuevo ''será llamada'' adúltera (Ro 7:3). El hilo común es la designación pública y oficial, ya sea del cielo o de la sociedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5543', 'spa', 'Bondadoso, benévolo, benigno; bueno, agradable, sano en calidad; fácil o bien ajustado (referido a un yugo).', 'Adjetivo cuya calidez permea cada uno de sus usos, χρηστός describe el carácter de un Dios que es bondadoso con los ingratos (Lucas 6:35), la bondad que debiera conducir al arrepentimiento (Romanos 2:4) y la amabilidad mutua que los creyentes se deben unos a otros (Efesios 4:32). Aplicado al vino, significa ''bueno'' — bien añejado y agradable al paladar (Lucas 5:39). Su aparición más célebre se encuentra en la invitación de Jesús: ''Mi yugo es χρηστός'' (Mateo 11:30) — no áspero sino bien ajustado, cómodo, moldeado a la medida de quien lo lleva. El español distingue ''bondadoso'' de ''bueno'' y de ''fácil'', correspondiendo con precisión a los tres sentidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5544', 'spa', 'Bondad, benignidad, generosidad -- excelencia moral expresada como trato benevolo y compasivo hacia los demas. El sustantivo χρηστότης (chrestotes) de', 'Bondad, benignidad, generosidad -- excelencia moral expresada como trato benevolo y compasivo hacia los demas. El sustantivo χρηστότης (chrestotes) denota bondad, benignidad o generosidad, una cualidad que es simultaneamente virtud moral y beneficencia activa. Pablo lo emplea como atributo divino: la bondad de Dios conduce al arrepentimiento (Ro 2:4), su bondad y severidad se mantienen en deliberada tension (Ro 11:22), y su bondad sobreabundante hacia nosotros en Cristo Jesus se manifiesta para todas las edades (Ef 2:7; Tit 3:4). Tambien aparece como fruto del Espiritu (Ga 5:22) y marca del ministerio apostolico autentico (2 Co 6:6). El trasfondo del termino en la filosofia moral helenistica, donde χρηστότης describia la benevolencia del gobernante ideal, enriquece el retrato paulino de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5545', 'spa', 'Unción; gracia espiritual o investidura de poder por medio del Espíritu Santo', 'Este sustantivo se refiere a una unción, pero en el Nuevo Testamento posee un sentido exclusivamente espiritual. En 1 Juan 2:20, 27 (tres apariciones), la ''unción'' es el don del Espíritu Santo que enseña a los creyentes y les permite discernir la verdad del error. Juan escribe: ''Vosotros tenéis la unción del Santo'' y ''la unción que habéis recibido de él permanece en vosotros''. Esta unción espiritual tiene su paralelo en las prácticas del Antiguo Testamento donde sacerdotes y reyes eran ungidos con aceite, pero ahora significa la presencia interior y el ministerio de enseñanza del Espíritu para todos los creyentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5546', 'spa', 'Cristiano; seguidor de Cristo, persona que pertenece al Mesías', 'Este término designa a un seguidor de Jesucristo. La palabra en sí significa ''perteneciente a Cristo'' o ''partidario de Cristo'', formada con el sufijo latino ''-ianus'' que indica lealtad o asociación. Hechos 11:26 registra que ''a los discípulos se les llamó cristianos por primera vez en Antioquía'', probablemente como designación dada por personas ajenas a la comunidad. Cuando Agripa dice a Pablo: ''Por poco me persuades a ser cristiano'' (Hechos 26:28), emplea el término como otros lo reconocerían. En 1 Pedro 4:16, Pedro escribe que sufrir ''como cristiano'' no es motivo de vergüenza, sino una oportunidad para glorificar a Dios. El nombre identifica a los creyentes con su Señor crucificado y resucitado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5547', 'spa', 'Cristo, Mesías — el Ungido, usado como título y nombre propio de Jesús de Nazaret.', 'Χριστός (''ungido'') traduce el hebreo מָשִׁיחַ y aparece 540 veces en el Nuevo Testamento, funcionando tanto como título mesiánico cuanto como nombre propio virtual. En su uso titular (''el Cristo'', Mt 16:16), lleva todo el peso de la teología veterotestamentaria de la unción — la consagración de reyes, sacerdotes y profetas. En su uso como nombre (''Jesucristo'', ''Cristo Jesús''), particularmente dominante en las cartas de Pablo, se ha fusionado tanto con el nombre personal que la teología de la unción pasa a un segundo plano. La evidencia multilingüe — español ''Cristo'', francés ''Christ'', alemán ''Christus'' — muestra una notable uniformidad como préstamo léxico más que como concepto traducido.');